            'steps' => '[{"duration": "3 mins", "how_to_do": "Cleanse the entire face using a gentle gel cleanser; massage in circular motions for 2 minutes and wipe with damp gauze. Degrease lightly with alcohol-free toner, avoiding eyes and lips. Proceed when skin is clean and dry.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Toner/degreaser", "Gauze"]}, {"duration": "10 mins", "how_to_do": "Start with Cutin Removal Spatula for 2 minutes to loosen debris. Switch to Bubble Pen: apply SA2 on nose, forehead and chin (2 gentle passes, low–medium suction; keep handpiece moving). Use AS1 on cheeks (1–2 passes, low suction). Avoid over active inflamed papules and stop if petechiae appear.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula", "Suction Probe / Bubble Pen", "Hydrafacial Serum SA2 (T-zone)", "Hydrafacial Serum AS1 (cheeks)"]}, {"duration": "6 mins", "how_to_do": "Targeted comedone extraction on nose and central forehead. Hold skin taut; use short gliding strokes with low suction (level 1–2). Limit to 1–2 passes per area to prevent bruising. Stop when only mild erythema and reduced sebum plugs are visible.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Suction Probe / Bubble Pen"]}, {"duration": "5 mins", "how_to_do": "Perform gentle lymphatic drainage massage: begin at the neck, move to jawline and cheeks with light pumping strokes toward preauricular nodes, then forehead to temples. Avoid heavy pressure over active lesions. End when edema reduces and skin appears relaxed.", "step_number": "4", "ingredients_equipments": ["Massage cream or gel"]}, {"duration": "4 mins", "how_to_do": "Protect corners of nose/eyes/lips with petroleum jelly. Apply a thin, even layer of Gel Based Mandelic Peel using a brush, starting with cheeks, then forehead and chin; avoid direct contact with eyes and mucosa. Keep for 2–3 minutes (first sitting), monitor for stinging not exceeding 5/10. Neutralize thoroughly with cool wet gauze; stop immediately if frosting or excessive erythema appears.", "step_number": "5", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan/cool saline", "Neutralizer/wet gauze", "Petroleum jelly"]}, {"duration": "5 mins", "how_to_do": "Place eye shields. Mix a few drops of PDRN with Hyaluronic Acid and apply around the orbital rim (not on eyelids). Use ocular ultrasound probe on low-intensity continuous mode; glide gently from inner to outer canthus, 2–3 passes per eye for 2–3 minutes each. Keep the probe moving to avoid heat build-up.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Ocular Ultrasound Infusion Probe", "PDRN (polydeoxyribonucleotide)", "Hyaluronic Acid", "Ultrasound gel", "Eye shields"]}, {"duration": "7 mins", "how_to_do": "Apply a thin layer of TRX A mixed with Hyaluronic Acid over the face focusing on forehead, cheeks and perioral pigmentation. Use face ultrasound probe on low-intensity continuous mode; perform slow overlapping strokes for 7 minutes (1–2 passes/zone). Avoid open lesions. Wipe excess serum after infusion.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Face Ultrasound Infusion Probe", "Tranexamic Acid (TRX A)", "Hyaluronic Acid", "Ultrasound gel"]}, {"duration": "14 mins", "how_to_do": "Position LED panel 10–15 cm from face. With eye shields on, run Blue mode for 7 minutes for acne bacteria control, then switch to Red mode for 7 minutes to reduce inflammation and support healing. Stop if patient reports photosensitivity or discomfort.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine", "Eye shields"]}, {"duration": "10 mins", "how_to_do": "Mix Hydrate mask to a smooth paste and apply an even layer over full face, avoiding nostrils and eyes. Leave undisturbed for 8–10 minutes for occlusive hydration and barrier support. Peel off gently from edges; remove residues with damp gauze.", "step_number": "9", "ingredients_equipments": ["Peel-off Mask: Hydrate", "Bowl and spatula"]}, {"duration": "3 mins", "how_to_do": "Use oxygen spray to mist Hyaluronic Acid evenly across face for cooling and hydration for 2–3 minutes at low pressure, keeping nozzle 10–15 cm away. Avoid directing spray into eyes or nostrils.", "step_number": "10", "ingredients_equipments": ["Hydrafacial Oxygen Injection (Hydra spray)", "Hyaluronic Acid solution"]}, {"duration": "3 mins", "how_to_do": "Finish with Serum + Moisturizer + Sunscreen: apply 2–3 pumps of HA serum with gentle patting, seal with a non-comedogenic moisturizer, then apply SPF 50 sunscreen evenly. Advise patient to avoid heat/scrubs/actives for 48 hours and reapply sunscreen every 3 hours when outdoors.", "step_number": "11", "ingredients_equipments": ["Hydrating serum (Hyaluronic Acid)", "Moisturizer (non-comedogenic)", "Broad-spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-10 06:46:15',
                'updated_at' => '2025-11-10 06:46:15',
            ),
