            'preparations_checklist_for_therapist' => '["Sanitize room, trolley and handpieces; place fresh linens, headband and gauze.", "Verify consent, allergies, medications, last peel/laser; confirm not pregnant and no blood thinners.", "Confirm sun exposure <1 hr; no upcoming travel/events this week; take baseline photos.", "Prime Hydrafacial Machine; set low–moderate vacuum; test suction on gloved hand.", "Keep tips ready: Cutin Removal Spatula, Suction/Bubble pen, Face & Ocular Ultrasound Infusion probes.", "Prepare Gel Based Mandelic Peel with timer, petroleum for corners and neutralizer/cool saline.", "Lay out serums: Hyaluronic Acid, TRX A (Tranexamic Acid), PDRN; barrier moisturizer and SPF 50.", "Set LED Light Therapy Machine to Red mode; keep eye shields ready.", "Ensure cold pack/fan available; maintain room temperature 22–24°C.", "Explain procedure sequence and expected sensations; reconfirm consent."]',
            'concerns_addressed' => '[{"concern": "Dry Skin & Barrier Health", "target_value": "Balanced / Barrier Score 0", "current_value": "Dry / Barrier Score 1"}, {"concern": "Glow & Dullness", "target_value": "Glow Score 2–3", "current_value": "Glow Score 1"}, {"concern": "Pigmentation (prep phase)", "target_value": "Score 1–2 over course", "current_value": "Score 3 - Moderate"}]',
            'steps' => '[{"duration": "4 mins", "how_to_do": "Cleanse face and neck using gentle circular strokes for 2–3 minutes; rinse and pat dry. Avoid rubbing peri‑orbital and lip areas.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Mild cleanser"]}, {"duration": "6 mins", "how_to_do": "Exfoliate with AS1 using one slow overlapping pass over entire face; keep suction low–moderate and tip at 45°. Stop if diffuse erythema occurs.", "step_number": "2", "ingredients_equipments": ["Hydrafacial - Cutin Removal Spatula", "Hydrafacial Serum AS1"]}, {"duration": "5 mins", "how_to_do": "Perform gentle extractions on nose and chin with short strokes; keep constant movement to prevent suction marks.", "step_number": "3", "ingredients_equipments": ["Hydrafacial - Suction/Bubble pen"]}, {"duration": "4 mins", "how_to_do": "Protect nose folds and lip corners with petroleum. Apply thin even coat avoiding eyelids; contact 3–4 minutes (aim for mild tingling only). Neutralize thoroughly and blot dry.", "step_number": "4", "ingredients_equipments": ["Gel Based Mandelic Peel", "Petroleum jelly", "Neutralizer/cool saline"]}, {"duration": "6 mins", "how_to_do": "Layer HA + PDRN and glide ultrasound probe in slow circular passes over face and neck for 6 minutes to enhance penetration and repair.", "step_number": "5", "ingredients_equipments": ["Hydrafacial - Face Ultrasound Infusion Probe", "Hyaluronic Acid", "PDRN"]}, {"duration": "4 mins", "how_to_do": "Apply TRX A around peri‑orbital area, staying 5–7 mm away from lash line; infuse 2 minutes per side to start under‑eye brightening.", "step_number": "6", "ingredients_equipments": ["Hydrafacial - Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)"]}, {"duration": "6 mins", "how_to_do": "Perform gentle facial and lymphatic drainage massage: effleurage center-to-periphery, light pumping at preauricular and submandibular nodes; avoid heavy pressure.", "step_number": "7", "ingredients_equipments": ["Massage cream/HA serum"]}, {"duration": "8 mins", "how_to_do": "Position LED 15–20 cm from face; irradiate 8 minutes to calm skin and support collagen. Avoid if photosensitizers are in use.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine - Red mode", "Eye shields"]}, {"duration": "3 mins", "how_to_do": "Finish with serum (TRX A/HA blend), barrier moisturizer, and sunscreen. Advise avoiding steam/sauna and exfoliants for 24–48 hours.", "step_number": "9", "ingredients_equipments": ["Barrier Moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
