            'concerns_addressed' => '[{"concern": "Texture + Open Pores", "target_value": "Grade 0–1 (smooth)", "current_value": "Grade 1"}, {"concern": "Glow & Hydration", "target_value": "Glow Score 2–3 / Hydration Score 0", "current_value": "Glow Score 1 / Hydration Score 1"}, {"concern": "Peri‑oral/Lip Pigmentation", "target_value": "Reduced", "current_value": "Present"}]',
            'steps' => '[{"duration": "6 mins", "how_to_do": "One to two gentle passes focusing on T‑zone; low suction to prevent marks; rinse and dry.", "step_number": "1", "ingredients_equipments": ["Hydrafacial - Cutin Spatula", "AS1"]}, {"duration": "3 mins", "how_to_do": "Apply thin coat to face including peri‑oral region; contact 2–3 minutes; neutralize thoroughly.", "step_number": "2", "ingredients_equipments": ["Gel Based Mandelic Peel", "Neutralizer"]}, {"duration": "6 mins", "how_to_do": "Infuse HA across face; optionally apply Vitamin C locally on residual pigment; continuous slow strokes for 6 minutes.", "step_number": "3", "ingredients_equipments": ["Face Ultrasound Infusion", "Hyaluronic Acid", "Vitamin C (optional for spots)"]}, {"duration": "6 mins", "how_to_do": "Apply hydrating mask evenly; leave 6 minutes; peel off and clean residue.", "step_number": "4", "ingredients_equipments": ["Peel‑off Mask - Hydrate"]}, {"duration": "3 mins", "how_to_do": "Finish with serum, barrier moisturizer and sunscreen; advise maintenance visit every 4–6 weeks.", "step_number": "5", "ingredients_equipments": ["TRX A/HA Serum", "Moisturizer", "SPF 50"]}]',
