            'preparations_checklist_for_therapist' => '["Sanitize room and bed; arrange fresh towels, headband, gloves, gauze and disposable tips.", "Review consent, medical history, last peel/laser, current medications and confirm no pregnancy/breastfeeding.", "Allergy check for Vitamin C/Aloe; plan to skip if any sensitivity develops during patch test.", "Set up Hydrafacial Machine; select Cutin Removal Spatula and Suction Probe/Bubble Pen; load serums AS1 (cleanse/exfoliate), SA2 (oil control for T‑zone), A03 (hydration for cheeks).", "Prepare jet/infusion solutions: Tranexamic Acid (TRX A), Hyaluronic Acid, PDRN; keep sterile ultrasound gel.", "Prepare Radio frequency Machine with facial RF handpiece; verify grounding/safety; keep IR thermometer ready.", "Set LED Light Therapy to Green (525 nm) and Red (630–635 nm) presets.", "Arrange eye protection: patient goggles and cotton pads for LED/RF; protect eyebrows and lips as needed.", "Prepare peel‑off Brighten mask bowl, spatula; keep waste bin and timer/stopwatch.", "Keep post‑care products ready: Hyaluronic serum, barrier moisturizer, broad‑spectrum SPF 50.", "Click standardized pre‑treatment photos; explain expected sensations and downtime (minimal).", "Ensure comfortable room temperature and patient positioning with neck support for RF over jawline."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1 - Minimal / Almost Clear", "current_value": "3 - Moderate"}, {"concern": "Under-Eye Vascularity/Structural Shadows", "target_value": "Score 0 - None", "current_value": "Score 2 - Moderate"}, {"concern": "Texture + Open Pores", "target_value": "Grade 0 - Clear / Smooth", "current_value": "Grade 2 - Mild"}, {"concern": "Comedonal Density", "target_value": "Score 0 - No Comedones", "current_value": "Score 1 - Mild Comedonal Activity"}, {"concern": "Skin Hydration & Barrier", "target_value": "Score 0 - Excellent Hydration / Strong Barrier", "current_value": "Score 1 - Mild Dehydration / Mildly Compromised Barrier"}, {"concern": "Skin Luminosity / Glow", "target_value": "Score 2–3 (Healthy to Radiant)", "current_value": "Score 1 - Mild Glow"}, {"concern": "Jawline Sagging", "target_value": "Grade 1 or sharper contour", "current_value": "Grade 1 - Very Mild"}, {"concern": "Regional Oil Distribution", "target_value": "Score 0 - Even / Balanced Oil Distribution", "current_value": "Score 1 - T-zone Predominant"}, {"concern": "Skin Sensitivity/Redness", "target_value": "Score 0 - None", "current_value": "Score 1 - Mild"}]',
            'steps' => '[{"duration": "4 mins", "how_to_do": "Double cleanse. Apply gentle cleanser, massage 1–2 mins, remove with damp gauze. Degrease T‑zone lightly with micellar water. Ensure skin is fully dry before device work. Avoid aggressive rubbing on sensitive areas.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Gentle cleanser", "Micellar water"]}, {"duration": "4 mins", "how_to_do": "Use spatula at low intensity to lift superficial keratin. Glide at 30–45° angle from center outward; 1 pass per zone. Stop if erythema or discomfort >3/10. Pat dry.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine - Cutin Removal Spatula (Exfoliator)"]}, {"duration": "6 mins", "how_to_do": "Perform hydra-exfoliation over full face with AS1. Use low–medium vacuum (18–22 kPa), slow linear passes; 2 passes on cheeks/forehead, 1 pass peri-oral. Avoid active irritation. End when uniform, mild pinkness appears.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe/Bubble Pen", "Hydrafacial Serum AS1 (Cleanse & Exfoliate)"]}, {"duration": "3 mins", "how_to_do": "Target T‑zone (nose, central forehead, chin) with SA2 for sebum control. Single pass with medium vacuum on nose; quick spot sweeps around alar creases. Do not exceed 3 minutes to prevent over-exfoliation.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe", "Hydrafacial Serum SA2 (Oil Control)"]}, {"duration": "6 mins", "how_to_do": "Perform gentle lymphatic drainage: effleurage strokes from mid-face to preauricular nodes, then down to supraclavicular area. Pressure light–moderate; 6–8 strokes per pathway. Avoid pressing directly over thyroid.", "step_number": "5", "ingredients_equipments": ["Manual massage cream", "Lymphatic drainage technique"]}, {"duration": "6 mins", "how_to_do": "Under-eye infusion: mix TRX A with a few drops of HA. Use ocular ultrasound probe with light gel, circular motions from inner canthus to lateral canthus. 3 mins per eye. Keep 0.5–1 cm away from lash line; avoid globe pressure.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "Tranexamic Acid (TRX A)", "Hyaluronic Acid"]}, {"duration": "6 mins", "how_to_do": "Infuse PDRN across full face for barrier repair and hydration. Use ultrasound probe in overlapping circles, 2–3 passes per zone. Maintain continuous glide with gel to prevent hot spots. Wipe excess.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine - Face Ultrasound Infusion Probe", "PDRN (polydeoxyribonucleotide)"]}, {"duration": "10 mins", "how_to_do": "RF skin tightening for jawline/lower face. Apply gel; work in small zones with 1–2 MHz RF, target epidermal temperature 40–42°C. Slow circular strokes, 2–3 passes each side for 5 mins total per side. Stop if excessive heat or erythema; avoid thyroid.", "step_number": "8", "ingredients_equipments": ["Radio frequency Machine", "Conductive gel", "IR thermometer"]}, {"duration": "14 mins", "how_to_do": "Apply eye shields. Use Green LED (525 nm) 7 mins for pigmentation and redness modulation, followed immediately by Red LED (630–635 nm) 7 mins for collagen and healing. Keep device 10–15 cm from face. Discontinue if photosensitivity or discomfort occurs.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine - Green & Red", "Eye shields"]}, {"duration": "8 mins", "how_to_do": "Apply an even layer of Brighten peel‑off mask, avoiding hairline and brows. Leave for 6–8 mins until set; peel from edges upward. Skip if active irritation is noted; switch to Calming mask if needed.", "step_number": "10", "ingredients_equipments": ["Peel‑off Mask - Brighten"]}, {"duration": "3 mins", "how_to_do": "Finishers: Press a thin layer of Hyaluronic Acid serum over face and under-eye, follow with barrier moisturizer. Apply SPF 50 generously to all exposed areas. Provide post‑care: avoid heat/scrubs for 24–48 hrs and reapply sunscreen every 3 hours in daytime.", "step_number": "11", "ingredients_equipments": ["Hyaluronic Acid serum", "Barrier Moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-11 09:10:47',
