            'preparations_checklist_for_therapist' => '["Sanitize room and trolley; place fresh linens, headband, gauze, and disposable towels.", "Verify consent form, medical history, allergies, last peel/laser/retinoid use; confirm not pregnant/breastfeeding.", "Assess Fitzpatrick type and test patch for Mandelic Peel on mandibular area.", "Set up Hydrafacial Machine with Cutin Removal Spatula and Suction Probe; load Hydrafacial Serum A03 (hydration) and AS1 (cleanse/exfoliate).", "Prepare Gel Based Mandelic Peel with timer, water/neutralizer, cotton buds, and fan for comfort.", "Prepare jet/ultrasound infusion solutions: Tranexamic Acid (TRX A), Hyaluronic Acid, and PDRN; keep Ocular and Face Ultrasound Infusion Probes ready.", "Ready Radio frequency Machine with conductive gel; check for pacemakers/metal implants; skin temperature probe available.", "Set LED Light Therapy Machine to Green and Red modes; place eye shields for patient.", "Keep Peel-off Hydrate mask, mixing bowl/spatula, and cold packs/Ice Probe for post-procedure calming.", "Arrange finishing products: soothing hydrating serum, ceramide moisturizer, and broad-spectrum SPF 50 sunscreen."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1–2 (Minimal to Mild)", "current_value": "4 - Marked"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0–1 (Clear to Very Mild)", "current_value": "Grade 3 - Moderate"}, {"concern": "Skin Hydration", "target_value": "0–1 (Excellent to Mild Dehydration)", "current_value": "2 - Moderate Dehydration"}, {"concern": "Barrier Health", "target_value": "0–1 (Strong to Mildly Compromised)", "current_value": "2 - Moderately Compromised"}, {"concern": "Jawline Sagging", "target_value": "Grade 1 - Very Mild", "current_value": "Grade 3 - Moderate"}, {"concern": "Comedonal Density", "target_value": "0 - No Comedones", "current_value": "1 - Mild Comedonal Activity"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "2–3 (Healthy Glow to Radiant)", "current_value": "0 - Dull / Lackluster"}, {"concern": "PeriOrbital Health", "target_value": "None to Mild", "current_value": "Moderate"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Start with a gentle cleanse; apply Serum A03 and use the Cutin Removal Spatula on damp skin for superficial exfoliation across full face and neck. Use light pressure, short strokes. Avoid active lesions. Rinse and pat dry before next step.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Mild cleanser", "Hydrafacial Serum A03"]}, {"duration": "6 mins", "how_to_do": "Perform hydra-cleansing passes with AS1 using the Suction Probe. Use linear strokes on cheeks and circular motions over T‑zone. 1–2 passes per area; suction at low–medium to prevent petechiae. Stop if pinpoint erythema or discomfort occurs.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum AS1", "Suction Probe / Bubble Pen"]}, {"duration": "4 mins", "how_to_do": "Apply a thin, even layer of Gel Based Mandelic Peel avoiding eyes/nasal folds/lips. Observe frosting/erythema; contact time 2–4 minutes based on tolerance. Fan for comfort. Neutralize thoroughly with water/gauze. Do not combine with any other medium/deep peel today.", "step_number": "3", "ingredients_equipments": ["Gel Based Mandelic Peel", "Timer", "Neutralizer/water"]}, {"duration": "6 mins", "how_to_do": "Targeted extractions for comedones on nose and medial cheeks. Keep suction low and glide continuously to avoid hickies. Limit to 2 passes per area. Wipe sebum debris and reassess comfort.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "7 mins", "how_to_do": "Perform manual lymphatic drainage: gentle effleurage from mid-face to pre-auricular nodes and down to supraclavicular nodes (3 cycles/side). Follow with oxygen spray for 1–2 mins for soothing. Stop if excessive redness occurs.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine", "Oxygen Injection (Hydra spray)", "Lymphatic drainage massage oil/gel"]}, {"duration": "11 mins", "how_to_do": "Using the Face Ultrasound Probe with coupling gel, infuse TRX A over pigmented areas (malar, upper lip, forehead) in slow overlapping strokes for 4–5 mins; then layer Hyaluronic Acid across full face for 3 mins. Switch to PDRN for 2–3 mins focusing on dry/flaky zones to support barrier. Use Ocular Probe for under-eye—diluted TRX A + HA for 1–2 mins per side. Keep probe constantly moving; avoid globe pressure; stop if stinging persists.", "step_number": "6", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid", "PDRN"]}, {"duration": "10 mins", "how_to_do": "Apply conductive gel; use RF handpiece for lower cheeks and jawline. Energy: low–moderate (aim skin temp 38–40°C). 3–4 slow passes per zone with continuous motion, 5 mins per side. Avoid thyroid area and any metal implants. Discontinue if hot spots or discomfort.", "step_number": "7", "ingredients_equipments": ["Radio frequency Machine", "Conductive gel"]}, {"duration": "12 mins", "how_to_do": "Place eye shields. Use Green light for 6 mins to calm melanocyte activity, then Red light for 6 mins to support healing and collagen. Keep face clean and dry; no photosensitizers. Stop if migraine or light sensitivity occurs.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine (Green + Red)", "Eye shields"]}, {"duration": "8 mins", "how_to_do": "Mix and apply a uniform layer of Hydrate peel-off mask over face, avoiding nostrils and eyes. Leave for 6–8 mins until semi-solid, then peel from edges. This step boosts hydration and calms post-LED warmth.", "step_number": "9", "ingredients_equipments": ["Peel-off Hydrate Mask"]}, {"duration": "2 mins", "how_to_do": "Glide Ice Probe gently over treated zones, especially peri‑orbital and jawline, for 1–2 mins to reduce any residual erythema. Do not hold stationary to prevent cold burns.", "step_number": "10", "ingredients_equipments": ["Hydrafacial Ice Probe or cold pack"]}, {"duration": "4 mins", "how_to_do": "Finish with a thin layer of hydrating serum, seal with ceramide-based moisturizer, then apply SPF 50 evenly to all exposed areas. Advise patient to avoid heat/sun for 24–48 hours and to reapply sunscreen every 3 hours.", "step_number": "11", "ingredients_equipments": ["Hydrating serum (Hyaluronic Acid/PDRN)", "Ceramide moisturizer", "Broad-spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-14 07:29:35',
                'updated_at' => '2025-11-14 07:29:35',
