                'week' => 1,
            'preparations_checklist_for_therapist' => '["Disinfect bed, trolley, handpieces; lay fresh headband, towels, and disposable sheets.", "Verify consent, medical history, allergies, pregnancy/breastfeeding, last peel/laser, and blood thinners.", "Remove makeup and cleanse skin; take standardized pre-treatment photographs.", "Prime Hydrafacial Machine: fill AS1 (cleanse/exfoliate) and SA2 (oil control) bottles; check suction levels; prepare Cutin Removal Spatula and Suction Probe.", "Prepare Jet/Ultrasound infusion serums: Tranexamic Acid (TRX A) and Hyaluronic Acid; have PDRN ready for peri‑orbital area.", "Lay out Gel Based Pumpkin Peel with timer, fan, gauze, cotton buds, cool saline/neutralizer bowl.", "Set up Radio frequency Machine with bipolar facial handpiece; check grounding/cords; keep conductive gel ready; set temperature monitor/IR thermometer.", "Prepare LED Light Therapy Machine on Red mode; verify protective eye shields for patient.", "Keep peel‑off Hydrate mask, moisturizer, and broad‑spectrum SPF 50 accessible.", "Ensure room temperature is comfortable; maintain good lighting; brief patient on sensations and safety cues."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1 - Minimal / Almost Clear", "current_value": "3 - Moderate"}, {"concern": "Texture + Open Pores & Comedones", "target_value": "Grade 0 - Clear / Smooth; Score 0 - No Comedones", "current_value": "Grade 2 - Mild; Score 2 - Moderate"}, {"concern": "Skin Hydration & Glow", "target_value": "Score 0 - Excellent Hydration; Glow 2–3", "current_value": "Score 2 - Moderate Dehydration; Glow 1"}, {"concern": "Jawline Sagging", "target_value": "Grade 1 - Very Mild", "current_value": "Grade 3 - Moderate"}, {"concern": "Mild Sensitivity/Redness & Periorbital Fatigue", "target_value": "Sensitivity 0; Periorbital None-Mild", "current_value": "Sensitivity 1; Periorbital Moderate"}, {"concern": "Lip Pigmentation (supportive care)", "target_value": "Absent", "current_value": "Present"}]',
            'steps' => '[{"duration": "5", "how_to_do": "Cleanse the entire face and neck, pat dry. Using Hydrafacial AS1, perform one even pass over full face with low suction (level 1–2). Glide the tip in overlapping strokes for 2–3 minutes avoiding eyelids and lips. Stop if excessive erythema appears.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum AS1", "Cleanser"]}, {"duration": "7", "how_to_do": "Target T‑zone with SA2 for oil control. Keep suction at low‑moderate (level 2–3). Use the Cutin Removal Spatula to loosen keratin around nose/medial cheeks. Two gentle passes on oily areas only. Avoid active irritated patches.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum SA2", "Cutin Removal Spatula (Exfoliator)"]}, {"duration": "8", "how_to_do": "Perform comedone extraction with the suction probe focusing on nose and chin. Use short, lifting strokes; do not hover on one spot >2 seconds. Limit to 1 pass per area; stop if petechiae or capillary visibility increases.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "5", "how_to_do": "Apply a thin, even layer of Gel Based Pumpkin Peel to face avoiding eyes, corners of nose, and lips. Contact time 2–3 minutes for sensitive areas and up to 4 minutes for forehead/cheeks, monitoring for uniform pinkness only. Neutralize thoroughly with cool saline; blot dry.", "step_number": "4", "ingredients_equipments": ["Gel Based Pumpkin Peel", "Fan", "Gauze", "Cool Saline/Neutralizer"]}, {"duration": "8", "how_to_do": "Infuse TRX A on pigmented zones (forehead, malar, nose) using ultrasound probe with adequate gel; slow circular motions for 4 minutes. Follow with Hyaluronic Acid infusion for whole face for 3–4 minutes to rehydrate. Keep probe moving continuously; avoid thyroid area.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine - Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid"]}, {"duration": "4", "how_to_do": "Treat peri‑orbital area using ocular probe with a small amount of PDRN. Glide gently along orbital rim for 2 minutes each side; avoid direct pressure on the globe. Stop if patient reports visual flashes or discomfort.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "PDRN (polydeoxyribonucleotide)"]}, {"duration": "6", "how_to_do": "Perform light face and lymphatic drainage massage. Use effleurage strokes from mid‑face to preauricular nodes and clavicular nodes. Maintain gentle pressure only; avoid dragging on thin peri‑orbital skin. Wipe off residue.", "step_number": "7", "ingredients_equipments": ["Massage cream or hydrating gel"]}, {"duration": "12", "how_to_do": "Apply conductive gel to lower cheeks and jawline. Using bipolar RF handpiece at 1–2 MHz, medium energy, perform slow circular strokes targeting 40–42°C skin temperature (monitor every minute). Treat 5–6 minutes per side, 1–2 passes. Keep handpiece in motion; avoid thyroid and metallic implants.", "step_number": "8", "ingredients_equipments": ["Radio frequency Machine", "Conductive gel"]}, {"duration": "10", "how_to_do": "Place protective eye shields. Set LED Red mode, position panel 10–15 cm from face. Expose for 10 minutes to calm post‑procedure erythema and support collagen. Discontinue if patient feels heat or stinging.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine (Red Mode)", "Protective eye shields"]}, {"duration": "8", "how_to_do": "Apply a uniform layer of Hydrate mask over face and jawline. Allow to set for 6–8 minutes. Peel off from edges in one piece; wipe any residue with damp gauze.", "step_number": "10", "ingredients_equipments": ["Peel-off Hydrate Mask"]}, {"duration": "2", "how_to_do": "If mild redness persists, glide the ice probe over cheeks and jawline for 1–2 minutes to soothe. Avoid prolonged contact over bony prominences.", "step_number": "11", "ingredients_equipments": ["Hydrafacial Ice Probe (optional)"]}, {"duration": "4", "how_to_do": "Finishers: pat a thin layer of Tranexamic serum on pigmented areas; apply Hyaluronic serum over entire face; seal with moisturizer; apply SPF 50 generously. Ensure even coverage including neck and peri‑oral region. This is the mandatory final step.", "step_number": "12", "ingredients_equipments": ["Tranexamic Acid serum (spot)", "Hyaluronic Acid serum", "Moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-17 08:20:19',
                'updated_at' => '2025-11-17 08:20:19',
            ),
            20 => 
            array (
                'id' => 21,
                'assessment_id' => 11,
                'user_id' => 13,
                'plan_type' => 'single',
                'session_number' => 1,
            'title' => 'HydraBright RF Lift (Hydrafacial + RF Tightening + Targeted Infusion + LED)',
                'treatment_time' => '75 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize room, trolley, hydrafacial handpieces, RF probe; lay fresh towels, headband, and disposable sheets.", "Verify patient identity, obtain consent; check for allergies, pregnancy/breastfeeding, metal implants, pacemaker, active infections, and last peel/laser.", "Confirm no photosensitizing meds and no open lesions; remove contact lenses if any.", "Hydrafacial machine: power on; load Hydrafacial Serum AS1 and A03; keep SA2 for T‑zone; check suction at −18 to −22 inHg; prime lines.", "Set aside probes: Suction/Bubble pen, Cutin Removal Spatula, Face Ultrasound Infusion Probe, Ocular Ultrasound Probe, Ice Probe.", "Radio frequency machine: check return plate/grounding if applicable; set to 1–2 MHz, target skin temp 38–40°C; test on gloved hand.", "Prepare serums for infusion: Tranexamic Acid (TRX A), Vitamin C (if no sensitivity), Hyaluronic Acid; decant into sterile cups.", "Prepare LED Light Therapy Machine (Red mode); place appropriate eye shields for patient.", "Peel‑off mask (Brighten) and hydrating gel, cotton pads, gauze; oxygen injection (hydra spray) bottle filled with sterile distilled water.", "Keep soothing gel, cold pack/Ice probe, and timer ready; ensure neutralizer/clean water available for accidental stinging.", "Set room lighting and temperature comfortable; place waste bin and sharps container if needed.", "Capture pre‑treatment photos and reconfirm targeted concerns with patient."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1 - Minimal / Almost Clear", "current_value": "3 - Moderate"}, {"concern": "Texture + Open Pores", "target_value": "Grade 0 - Clear / Smooth", "current_value": "Grade 2"}, {"concern": "Visual Acne / Comedones", "target_value": "Grade 0 / Score 0", "current_value": "Grade 1 / Score 1"}, {"concern": "Skin Hydration & Glow", "target_value": "Score 0; Glow Score 2–3", "current_value": "Score 2; Glow Score 1"}, {"concern": "Jawline Sagging", "target_value": "Grade 1", "current_value": "Grade 2"}, {"concern": "Skin Sensitivity/Redness", "target_value": "Score 0", "current_value": "Score 1"}, {"concern": "Peri‑orbital Mild Darkness", "target_value": "None", "current_value": "Mild"}, {"concern": "Regional Oil Distribution (T‑zone)", "target_value": "Score 0", "current_value": "Score 1"}, {"concern": "Lip Pigmentation", "target_value": "Absent", "current_value": "Present"}]',
            'steps' => '[{"duration": "5", "how_to_do": "Tie hair back. Double cleanse the face and neck; pat dry. Use the Cutin Removal Spatula on low vibration to lift superficial debris with wet gauze support for 2–3 minutes. Avoid active lesions and peri‑orbital skin. End when the skin is uniformly clean without visible residue.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Gentle cleanser", "Toner/Degreaser", "Cutin Removal Spatula (Exfoliator)"]}, {"duration": "8", "how_to_do": "Attach Bubble Pen; set vacuum to −18 to −20 inHg. Glide in linear overlapping strokes from forehead to chin using AS1 for cleanse + exfoliation. Maintain continuous movement; do not hover to prevent petechiae. One uniform pass on cheeks and two gentle passes on T‑zone.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum AS1"]}, {"duration": "4", "how_to_do": "Apply SA2 only on T‑zone for controlled BHA exfoliation; contact time 60–90 seconds while monitoring for frosting or undue erythema (should not occur). On cheeks simultaneously switch to A03 hydrating serum with one slow pass. Neutralize by rinsing with cool water if stinging persists beyond 6/10.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum SA2", "Hydrafacial Serum A03"]}, {"duration": "7", "how_to_do": "Perform gentle extractions on nose, chin, and medial cheeks at −20 to −22 inHg. Use short, quick passes; keep the tip moving and avoid repeated passes over fragile vessels. Stop when whiteheads/blackheads reduce and erythema remains mild.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "5", "how_to_do": "Manual lymphatic drainage massage: use light pressure strokes—supratrochlear to preauricular, infraorbital to parotid, and submandibular to supraclavicular. Repeat 5 cycles per pathway. Avoid pressing over thyroid and avoid strong pressure over peri‑orbital area.", "step_number": "5", "ingredients_equipments": ["Massage cream/gel (non‑comedogenic)"]}, {"duration": "12", "how_to_do": "Apply conductive gel over lower face. Use RF at 1–2 MHz; slow circular strokes along jawline and lower cheeks. Target temperature 38–40°C; 6 minutes each side, 2 passes. Keep probe moving to avoid hot spots; contraindicated in patients with pacemaker or metal implants. End when mild, even warmth is achieved.", "step_number": "6", "ingredients_equipments": ["Radio frequency Machine", "Lifting Probe (RF)", "Conductive gel"]}, {"duration": "8", "how_to_do": "Mix 2–3 ml cocktail (TRX A + Vitamin C + HA). With ultrasound probe set to medium intensity, glide slowly over forehead, cheeks, nose, chin for 8 minutes. Maintain continuous motion; avoid over bony prominences for long. Goal: enhanced penetration for pigment control and hydration.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine", "Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Vitamin C", "Hyaluronic Acid"]}, {"duration": "4", "how_to_do": "Apply a thin layer of HA around peri‑orbital area. Using ocular probe on low intensity, make gentle outward strokes 2 minutes per eye, staying 1 cm away from lash line. Stop if patient reports visual disturbances; purpose is to hydrate and reduce mild under‑eye darkness.", "step_number": "8", "ingredients_equipments": ["Hydrafacial Machine", "Ocular Ultrasound Infusion Probe", "Hyaluronic Acid"]}, {"duration": "2", "how_to_do": "Quick cooling with Ice Probe over RF‑treated zones to calm skin for 1–2 minutes. Keep device moving and avoid prolonged contact to prevent cold burns.", "step_number": "9", "ingredients_equipments": ["Ice Probe"]}, {"duration": "10", "how_to_do": "Place eye shields. Use Red LED for 10 minutes at manufacturer’s standard fluence to reduce inflammation and support collagen. Contraindications: photosensitizing drugs. End when timer completes—no heat sensation should persist.", "step_number": "10", "ingredients_equipments": ["LED Light Therapy Machine (Red mode)", "Eye shields"]}, {"duration": "8", "how_to_do": "Apply a uniform layer of Brighten peel‑off mask, avoiding eyes, nostrils, and lips. Leave for 8 minutes or until set. Lift from edges and remove in one piece. This step enhances radiance and soothes post‑procedure skin.", "step_number": "11", "ingredients_equipments": ["PeelOffMasks - Brighten"]}, {"duration": "3", "how_to_do": "Perform oxygen hydra spray across face for 2–3 minutes at 6–8 cm distance for cooling and hydration. Avoid direct stream into eyes or nostrils.", "step_number": "12", "ingredients_equipments": ["Oxygen Injection (Hydra spray)"]}, {"duration": "5", "how_to_do": "End protocol with Serum + Moisturizer + Sunscreen: layer TRX A serum over pigmented areas, follow with HA serum for whole face, seal with non‑comedogenic moisturizer, and finally apply SPF 50 generously on face, eyelids (thin layer), neck, and lips (SPF balm). Ensure patient remains indoors for at least 20 minutes post‑procedure.", "step_number": "13", "ingredients_equipments": ["TRX A (Tranexamic Acid) serum", "Hyaluronic Acid serum", "Moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-17 08:48:11',
                'updated_at' => '2025-11-17 08:48:11',
