                'plan_type' => 'single',
                'session_number' => 1,
                'title' => 'Brightening Hydrafacial + Mandelic Peel + Peri-orbital TRX Infusion + Jawline RF + Red LED',
                'treatment_time' => '75 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Disinfect room surfaces; prepare disposable headband, towels, gauze, cotton, wooden applicators, gloves, and waste bin.", "Review consent, check thyroid history, pregnancy status, blood thinners, last peel/laser, and allergies; document baseline photos.", "Confirm no recent strong home acids; perform mandelic peel patch test behind ear.", "Cleanse patient makeup; degrease with alcohol-free toner; remove contact lenses.", "Prepare Hydrafacial Machine: Cutin Removal Spatula, Suction Probe/Bubble Pen, Ice Probe, Face & Ocular Ultrasound Infusion Probes; verify suction and flow.", "Load Hydrafacial Serums: Hydrafacial Serum AS1 (cleanse/exfoliate) and A03 (hydration).", "Lay out jet infusion solutions: TRX A (Tranexamic Acid) and Hyaluronic Acid; label separate syringes/cups.", "Keep Gel Based Mandelic Peel and neutralizer/water spray ready; timer set for 3–5 mins.", "Set Radio frequency Machine or Hydrafacial Lifting Probe (RF) with gel; skin temp monitoring infrared thermometer.", "Prepare LED Light Therapy Machine (Red mode); verify eye shields for patient.", "Select Peel-Off Mask: Brighten mask; bowl and spatula ready.", "Ensure finishers: Hyaluronic Acid serum, non-comedogenic moisturizer, and broad-spectrum SPF 50 available."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1 - Minimal / Almost Clear", "current_value": "4 - Marked"}, {"concern": "Peri-orbital dark circles", "target_value": "None to Mild / Score 0–1", "current_value": "Severe / Score 3"}, {"concern": "Texture + Open Pores", "target_value": "Grade 0–1", "current_value": "Grade 2"}, {"concern": "Skin Hydration", "target_value": "Score 0", "current_value": "Score 2"}, {"concern": "Jawline Sagging", "target_value": "Grade 1", "current_value": "Grade 2"}, {"concern": "Comedonal Density", "target_value": "Score 0", "current_value": "Score 1"}, {"concern": "Skin Luminosity", "target_value": "Score 2–3", "current_value": "Score 1"}, {"concern": "Skin Sensitivity/Barrier", "target_value": "Score 0", "current_value": "Score 1"}, {"concern": "Lip Pigmentation (supportive care)", "target_value": "Absent", "current_value": "Present"}]',
            'steps' => '[{"duration": "4 mins", "how_to_do": "Cleanse entire face and neck with a gentle gel cleanser; rinse and pat dry. Degrease lightly with alcohol-free toner to ensure uniform peel penetration and better vacuum performance.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Mild cleanser", "Toner"]}, {"duration": "6 mins", "how_to_do": "Glide the cutin removal spatula with AS1 across forehead, cheeks, nose, and chin in overlapping strokes; 1–2 passes per zone, light pressure. Avoid peri‑orbital area. End when stratum corneum looks uniformly refined.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)", "Hydrafacial Serum AS1"]}, {"duration": "5 mins", "how_to_do": "Apply a thin, even layer of Gel Based Mandelic Peel on face, sparing eyelids and corners of mouth. Contact time 3–5 mins based on erythema/tingle; monitor continuously. Neutralize thoroughly with water spray; blot dry before next step.", "step_number": "3", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan brush", "Neutralizer/water spray"]}, {"duration": "6 mins", "how_to_do": "Perform comedone extraction focusing on nose, medial cheeks, and chin. Use low–medium suction to avoid purpura; keep probe moving with wet passes. Stop if petechiae appear.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "5 mins", "how_to_do": "Do gentle facial and lymphatic drainage massage: light effleurage from center to lateral face and down to preauricular and supraclavicular nodes. Avoid heavy pressure; aim for decongestion and relaxation.", "step_number": "5", "ingredients_equipments": ["Massage cream/gel", "Hands (manual technique)"]}, {"duration": "7 mins", "how_to_do": "Mix 1:1 Hyaluronic Acid and TRX A; use ultrasound probe at low intensity (1 MHz, ~0.5 W/cm²). Glide slowly over pigmented regions and cheeks for 7 mins to enhance penetration. Keep probe moving; avoid thyroid region on neck.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Face Ultrasound Infusion Probe", "Hyaluronic Acid", "TRX A (Tranexamic Acid)"]}, {"duration": "6 mins", "how_to_do": "Place eye shields. Use ocular probe at lowest intensity with gel; infuse a small amount of TRX A then HA along infra‑orbital hollow. Work from medial canthus outward, 2–3 slow passes per side. Do not apply over the globe; stop if excessive warmth occurs.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid"]}, {"duration": "10 mins", "how_to_do": "Target jawline and lower cheeks for tightening. RF 1–2 MHz; maintain skin temperature 38–40°C with continuous circular strokes. 5 mins each side. Keep probe moving; contraindicated over metal implants or pacemakers.", "step_number": "8", "ingredients_equipments": ["Hydrafacial Machine - Lifting Probe (RF) or Radio frequency Machine", "Conductive gel"]}, {"duration": "8 mins", "how_to_do": "Position LED panel 15–20 cm from face; select Red mode (630–650 nm). Expose for 8 mins to calm post‑procedure erythema and support collagen. Ensure eye shields remain on.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine - Red mode"]}, {"duration": "6 mins", "how_to_do": "Apply Brighten peel‑off mask in an even layer avoiding eyes. Allow to set for ~6 mins until semi‑solid; peel gently from edges and wipe residue with damp gauze.", "step_number": "10", "ingredients_equipments": ["Peel-Off Mask - Brighten"]}, {"duration": "2 mins", "how_to_do": "Briefly cool treated areas with Ice Probe to reduce warmth and seal pores; keep each zone under cooling for 15–20 seconds, avoid prolonged freezing.", "step_number": "11", "ingredients_equipments": ["Hydrafacial Machine - Ice Probe"]}, {"duration": "2 mins", "how_to_do": "Finish with a thin layer of Hyaluronic Acid serum, follow with ceramide-rich moisturizer, and apply SPF 50 evenly on all exposed areas. Confirm no residue on eyelids.", "step_number": "12", "ingredients_equipments": ["Hyaluronic Acid serum", "Ceramide moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-19 07:46:45',
