            22 => 
            array (
                'id' => 23,
                'assessment_id' => 16,
                'user_id' => 9,
                'plan_type' => 'single',
                'session_number' => 1,
                'title' => 'Hydration + Pigment Toning + RF Tightening Single-Session Boost',
                'treatment_time' => '80 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Disinfect room surfaces; set up fresh linens, headband, and disposables (tips, gauze, cotton, gloves).", "Verify consent, photo documentation, medical history, no photosensitizing meds, and last peel/laser > 1 week.", "Confirm no pregnancy/breastfeeding and no known allergies; reconfirm sun exposure (<1 hr) and no upcoming travel/social events.", "Hydrafacial Machine: power on; select Cutin Removal Spatula and Suction Probe/Bubble Pen; ensure waste jar is empty and tubing secured.", "Prepare serums/solutions: Hydrafacial Serum AS1 (cleanse/exfoliate as needed on T-zone), Hydrafacial Serum A03 (hydration), TRX A (Tranexamic Acid), PDRN, Hyaluronic Acid.", "Prepare probes: Face Ultrasound Infusion Probe and Ocular Ultrasound Infusion Probe; ensure coupling gel is ready.", "Radio frequency Machine: power on; attach facial handpiece; preset energy to 3–4/10; check proper grounding and tip integrity.", "LED Light Therapy Machine: verify Red and Green modes working; sanitize panel; set timers (6 min Green + 6 min Red).", "Lay out Hydrate peel-off mask, mixing bowl/spatula, and Ice Probe for post-care cooling.", "Safety setup: eye shields, tissue protection for corners of mouth/nostrils, neutral gel, facial fan/cold pack, and timer."]',
            'concerns_addressed' => '[{"concern": "Skin Type (Dry Skin)", "target_value": "Balanced/Normal Skin", "current_value": "Dry Skin"}, {"concern": "Skin Hydration", "target_value": "Score 0 - Excellent Hydration", "current_value": "Score 2 - Moderate Dehydration"}, {"concern": "Barrier Health", "target_value": "Score 0 - Strong / Healthy Barrier", "current_value": "Score 2 - Moderately Compromised"}, {"concern": "Superficial Pigmentation", "target_value": "1–2 (Minimal to Mild)", "current_value": "4 - Marked"}, {"concern": "Texture + Open Pores", "target_value": "Grade 0–1 (Clear to Very Mild)", "current_value": "Grade 2 - Mild"}, {"concern": "Visual Acne Grading", "target_value": "Grade 0 - Clear", "current_value": "Grade 1 - Very Mild"}, {"concern": "Comedonal Density", "target_value": "Score 0 - None", "current_value": "Score 1 - Mild"}, {"concern": "Superficial Wrinkles", "target_value": "Grade 1–2 (Very Mild to Mild)", "current_value": "Grade 3 - Moderate"}, {"concern": "Jawline Sagging", "target_value": "Grade 1–2 (Very Mild to Mild)", "current_value": "Grade 3 - Moderate"}, {"concern": "PeriOrbital Health", "target_value": "None to Mild", "current_value": "Moderate"}, {"concern": "Under-Eye Vascularity vs Structural Shadows", "target_value": "Score 0–1 (None to Mild)", "current_value": "Score 2 - Moderate"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "Score 2–3 (Healthy to Radiant)", "current_value": "Score 0 - Dull"}]',
            'steps' => '[{"duration": "4 mins", "how_to_do": "Cleanse entire face and neck with a gentle, non-foaming cleanser; remove with damp gauze. Pat dry. Ensure no occlusive residues remain, especially along hairline and nasal folds. Proceed only when skin is clean and dry.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Gauze", "Distilled water"]}, {"duration": "6 mins", "how_to_do": "Using the Cutin Removal Spatula, glide at 30–45° angle with light pressure across forehead, nose, chin, and cheeks. Apply Hydrafacial Serum AS1 primarily on the T-zone for gentle exfoliation. Perform 1–2 passes per zone; avoid overworking dry patches. Stop when stratum corneum appears softened and smooth without erythema.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)", "Hydrafacial Serum AS1"]}, {"duration": "6 mins", "how_to_do": "Switch to the Suction Probe. Infuse Hydrafacial Serum A03 while performing slow, overlapping passes (1 pass per line) over full face. Maintain low suction for dry skin; keep tip moving to avoid petechiae. Focus on cheeks and perioral dryness. End when uniform hydration sheen is visible.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum A03"]}, {"duration": "6 mins", "how_to_do": "Target comedone-prone T-zone with low suction. Use brief stationary suctions (≤1 second) for visible open comedones; avoid repeated suction on the same spot. Discontinue if erythema intensifies or capillary fragility is noted.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "6 mins", "how_to_do": "Perform manual lymphatic drainage: effleurage strokes from mid-face to pre-auricular nodes, then down to cervical chain; gentle pressure only. 6–8 strokes per pathway. Avoid direct pressure on the thyroid area. Continue until puffiness reduces and patient relaxation improves.", "step_number": "5", "ingredients_equipments": ["Massage medium (light gel/cream)"]}, {"duration": "12 mins", "how_to_do": "Apply conductive gel. Treat cheeks, jawline, and submental region with RF energy 3–4/10. Use slow circular or linear passes, keeping handpiece in motion. Aim for surface temperature comfort (warm but not hot). Duration 3–4 mins per zone; 2 passes total. Avoid bony prominences and thyroid. Stop immediately if hot spots or discomfort occur.", "step_number": "6", "ingredients_equipments": ["Radio frequency Machine"]}, {"duration": "7 mins", "how_to_do": "Apply a thin layer of TRX A to pigmented areas (malar cheeks, upper lip, temples). Glide Face Ultrasound Infusion Probe at low intensity with continuous motion for 5–7 minutes. Keep probe flat; avoid ocular area and mucosal lips. Wipe excess product before next step.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Coupling gel"]}, {"duration": "5 mins", "how_to_do": "Mix a small amount of PDRN with Hyaluronic Acid for periorbital hydration. Using the Ocular Probe on low intensity, perform gentle sweeps along the infraorbital rim, avoiding direct contact with the eyelid margin. 2–3 passes per side. Stop if tearing or irritation occurs.", "step_number": "8", "ingredients_equipments": ["Ocular Ultrasound Infusion Probe", "PDRN (polydeoxyribonucleotide)", "Hyaluronic Acid", "Coupling gel"]}, {"duration": "12 mins", "how_to_do": "Place eye shields. Position LED panel 10–15 cm from face. Run Green mode for 6 minutes (tone evening/pigment modulation), then Red mode for 6 minutes (healing and collagen support). Contraindicated in photosensitivity; stop if excessive warmth or discomfort.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine"]}, {"duration": "8 mins", "how_to_do": "Apply an even layer of Hydrate peel-off mask over face and neck, avoiding eyes and nostrils. Leave for 8 minutes until set. Gently peel upward; remove residues with damp gauze. Proceed only if skin appears calm without hotspots.", "step_number": "10", "ingredients_equipments": ["Hydrate peel-off mask"]}, {"duration": "3 mins", "how_to_do": "Glide the Ice Probe over treated areas for cooling and vasoconstriction. Keep continuous motion to avoid cold burns. Focus 30–45 seconds per zone until skin feels soothed.", "step_number": "11", "ingredients_equipments": ["Ice Probe"]}, {"duration": "4 mins", "how_to_do": "Finish with Serum + Moisturizer + Sunscreen: apply Hyaluronic Acid serum to entire face and neck, follow with a barrier-repair moisturizer, and finally a broad-spectrum SPF 50. Ensure even coverage; advise no washing for 6–8 hours.", "step_number": "12", "ingredients_equipments": ["Hyaluronic Acid (serum)", "Moisturizer", "Broad-spectrum sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-19 16:13:31',
                'updated_at' => '2025-11-19 16:13:31',
            ),
            23 => 
            array (
                'id' => 24,
                'assessment_id' => 17,
                'user_id' => 15,
                'plan_type' => 'single',
                'session_number' => 1,
            'title' => 'Laser Toning + Hydra-Calm Infusion (Single-Session Brightening & Hydration)',
                'treatment_time' => '90 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize bed, trolley, laser room surfaces; arrange fresh drapes/headband and disposables", "Review consent and contraindications: recent peels/lasers, photosensitizing meds, pregnancy/breastfeeding, allergies", "Confirm no travel/social event within 7 days and no intense sunburn today", "Set up Q‑Switch Laser (1064 nm primary, 532 nm optional); perform calibration and patch‑test area selection", "Prepare protective eyewear/eye shields for patient and staff; place laser warning signage", "Keep cold packs, soothing gel, sterile gauze, and fan ready", "Prime Hydrafacial Oxygen Injection and Ultrasound Infusion Probes; check coupling gel", "Dispense jet infusion solutions: TRX A (tranexamic acid), Hyaluronic Acid, PDRN", "Lay out Calming peel‑off mask; ensure timer and trash bin available", "Prepare finishing products: repair serum, non‑comedogenic moisturizer, broad‑spectrum SPF 50"]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1–2 (Minimal to Mild)", "current_value": "4 - Marked"}, {"concern": "Lip Pigmentation", "target_value": "Absent", "current_value": "Present"}, {"concern": "Skin Hydration", "target_value": "0 - Excellent Hydration", "current_value": "2 - Moderate Dehydration"}, {"concern": "Skin Sensitivity / Barrier", "target_value": "0–1 (No–Mild Sensitivity; Strong–Mildly Compromised Barrier)", "current_value": "2 - Moderate Sensitivity & 2 - Moderately Compromised Barrier"}, {"concern": "Skin Luminosity / Glow", "target_value": "2–3 (Healthy to Radiant)", "current_value": "0 - Dull / Lackluster"}, {"concern": "PeriOrbital Health", "target_value": "None to Mild", "current_value": "Moderate"}]',
            'steps' => '[{"duration": "6 mins", "how_to_do": "Cleanse face and lips thoroughly; pat dry. Degrease gently with alcohol swab on pigmented patches to ensure uniform laser response. Avoid over‑rubbing sensitive areas.", "step_number": "1", "ingredients_equipments": ["Gel cleanser", "Alcohol swab"]}, {"duration": "3 mins", "how_to_do": "Patch test at mandibular area: 1064 nm, 6–8 mm spot, 3 Hz, 400–500 mJ, single shot. Observe for 1–2 mins; proceed only if mild, transient erythema without blistering.", "step_number": "2", "ingredients_equipments": ["Q‑Switch Laser (patch test)"]}, {"duration": "22 mins", "how_to_do": "Full‑face laser toning: 1064 nm, 6–8 mm spot, 3–5 Hz, 450–700 mJ. Perform 2 uniform passes maintaining continuous motion; endpoint is mild erythema/instant tone brightening without frosting. Avoid open lesions and 0.5–1 cm around orbital rim.", "step_number": "3", "ingredients_equipments": ["Q‑Switch Laser 1064 nm", "Eye shields"]}, {"duration": "6 mins", "how_to_do": "Lips: single light pass at 1064 nm, 4–6 mm spot, 2–3 Hz, 200–350 mJ. Keep within dry vermilion (avoid wet mucosa). Stop if whitening or excessive heat occurs.", "step_number": "4", "ingredients_equipments": ["Q‑Switch Laser 1064 nm (lip pass)"]}, {"duration": "5 mins", "how_to_do": "Immediate cooling for 3–5 mins to reduce post‑laser warmth. Do not rub; dab gently.", "step_number": "5", "ingredients_equipments": ["Cold packs", "Sterile gauze"]}, {"duration": "5 mins", "how_to_do": "Deliver cooling oxygen mist across the face to soothe and prepare skin for infusion. Maintain 2–3 cm distance; keep eyes protected.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Oxygen Injection (Hydra spray)"]}, {"duration": "8 mins", "how_to_do": "Spot‑infuse TRX A over forehead and malar pigmentation in slow circular motions at low–moderate intensity ensuring gel coupling. Avoid vigorous pressure on freshly lasered skin.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)"]}, {"duration": "8 mins", "how_to_do": "Layer HA then PDRN and infuse over full face for hydration and barrier repair. Continue until product absorption and visible plumping.", "step_number": "8", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "Hyaluronic Acid", "PDRN"]}, {"duration": "6 mins", "how_to_do": "Peri‑orbital hydration: glide gently 0.5–1 cm below lash line with minimal pressure to improve under‑eye appearance. Avoid direct contact with eyelids.", "step_number": "9", "ingredients_equipments": ["Ocular Ultrasound Infusion Probe", "Hyaluronic Acid or PDRN"]}, {"duration": "6 mins", "how_to_do": "Perform light facial and lymphatic drainage massage: strokes from mid‑face to pre‑auricular nodes and from submental to deep cervical nodes. Keep pressure gentle due to recent laser.", "step_number": "10", "ingredients_equipments": ["Manual technique (massage oil/gel)"]}, {"duration": "10 mins", "how_to_do": "Apply eye shields. Use Red mode for 10 mins to calm erythema and enhance repair. Maintain safe distance per device manual.", "step_number": "11", "ingredients_equipments": ["LED Light Therapy Machine (Red mode)"]}, {"duration": "8 mins", "how_to_do": "Apply evenly; allow 8 mins to set; peel off gently to reduce heat and redness.", "step_number": "12", "ingredients_equipments": ["Calming peel‑off mask"]}, {"duration": "7 mins", "how_to_do": "Finish with serum + moisturizer + generous SPF 50. Provide strict post‑care: no scrubs/actives for 3–5 days, sun avoidance for 1 week, reapply SPF every 3 hours outdoors.", "step_number": "13", "ingredients_equipments": ["Repair Serum", "Non‑comedogenic Moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-20 12:49:10',
                'updated_at' => '2025-11-20 12:52:21',
            ),
