            'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1 - Minimal / Almost Clear", "current_value": "3 - Moderate"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0–1", "current_value": "Grade 2"}, {"concern": "Visual Acne Grading / Comedonal Density", "target_value": "Grade 0 / Score 0", "current_value": "Grade 1 / Score 1"}, {"concern": "Skin Hydration & Glow", "target_value": "Score 0–1 & Score 2–3", "current_value": "Score 2 & Score 1"}, {"concern": "Jawline Sagging", "target_value": "Grade 1", "current_value": "Grade 2"}, {"concern": "Peri‑orbital Health (vascular tint/hollowness)", "target_value": "None to Mild", "current_value": "Moderate"}, {"concern": "Lip Pigmentation", "target_value": "Absent", "current_value": "Present"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Cleanse entire face and neck with gentle gel cleanser for 2 minutes; rinse and pat dry. Degrease with alcohol-free prep on T‑zone to improve laser and hydrafacial efficacy. Ensure skin is fully dry before device steps.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Gentle cleanser", "Gauze"]}, {"duration": "10 mins", "how_to_do": "Glide Cutin Removal Spatula over forehead, cheeks, nose and chin in upward strokes with AS1 serum; 2 uniform passes per zone, light pressure. Avoid eyelids. End when mild smoothness and faint erythema appear.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine - Cutin Removal Spatula", "Hydrafacial Serum AS1 (Cleanse & Exfoliate)"]}, {"duration": "8 mins", "how_to_do": "Perform focused comedone extraction on nose and medial cheeks using SA2; suction level low–moderate. Keep the tip moving to prevent petechiae. Do 2 passes on nose, 1 pass on cheeks. Stop if bruising or capillary fragility noted.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe/Bubble Pen", "Hydrafacial Serum SA2 (Oil Control)"]}, {"duration": "6 mins", "how_to_do": "Perform gentle lymphatic drainage massage: effleurage from center outward to preauricular nodes, then down to supraclavicular area; repeat each stroke 5–7 times. Pressure should be light. Avoid over the thyroid and freshly extracted areas.", "step_number": "4", "ingredients_equipments": ["Manual technique", "Massage cream or gel"]}, {"duration": "10 mins", "how_to_do": "Apply TRX A evenly to face (avoid eyelids) and use ultrasound probe in circular motions for 5 minutes focusing on forehead and malar pigmentation; follow with Hyaluronic Acid infusion for 5 minutes to boost hydration. Keep probe continuously moving; wipe excess.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine - Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid) solution", "Hyaluronic Acid solution"]}, {"duration": "6 mins", "how_to_do": "For peri‑orbital area, apply diluted HA mixed with PDRN; run ocular probe gently along infra‑orbital region for 3 minutes per side. Maintain low energy setting and avoid direct contact with lash line. Stop if patient reports visual disturbance.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "PDRN solution", "Hyaluronic Acid (diluted)"]}, {"duration": "15 mins", "how_to_do": "Place metal eye shields. Start with test shot behind ear. For full-face toning: 1064 nm, 6–8 mm spot, energy 300–600 mJ (low fluence), 6–8 Hz, 2 passes with 10–20% overlap. End point: mild diffuse erythema and acoustic popping without frosting. Avoid direct shots on lips/eyelids. Cool with cold pack for 2 minutes post‑procedure.", "step_number": "7", "ingredients_equipments": ["Q‑Switch Laser (1064 nm)", "Metal eye shields", "Smoke evacuator", "Cold pack"]}, {"duration": "12 mins", "how_to_do": "Apply gel to lower face and jawline. Deliver RF at energy 4–6/10 with continuous motion; 2–3 passes per zone (jawline, submandibular, lower cheek), approx. 4 minutes each side. Maintain skin temperature warm but comfortable. Stop if excessive heat or erythema occurs.", "step_number": "8", "ingredients_equipments": ["Radio frequency Machine", "Coupling gel"]}, {"duration": "10 mins", "how_to_do": "Position LED panel 15–20 cm from face. Select Red mode. Treat for 10 minutes to calm post‑laser inflammation and promote collagen. Eyes protected with opaque goggles. End when timer completes.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine - Red mode"]}, {"duration": "10 mins", "how_to_do": "Apply Brighten peel‑off mask in an even layer avoiding eyes, nostrils and lips. Leave for 8–10 minutes until film sets; peel off from edges. This step enhances radiance post‑toning. Discontinue if burning/itching persists.", "step_number": "10", "ingredients_equipments": ["PeelOffMask - Brighten", "Spatula/brush"]}, {"duration": "3 mins", "how_to_do": "Dot a thin layer of TRX A on lip borders and localized pigmented macules; dab gently for 60 seconds and blot excess. Avoid licking; ensure no cracking or wounds.", "step_number": "11", "ingredients_equipments": ["TRX A spot solution (optional)", "Cotton bud"]}, {"duration": "10 mins", "how_to_do": "Finish the facial: apply generous HA serum over face and peri‑orbital area, seal with lightweight moisturizer, then apply SPF50 to all treated areas and lip sunscreen. Provide post‑care: avoid heat, gym, active acids or scrubs for 48–72 hours and reapply SPF every 3 hours.", "step_number": "12", "ingredients_equipments": ["Soothing Hyaluronic Acid serum", "Non‑comedogenic moisturizer", "Broad‑spectrum Sunscreen SPF50", "Lip SPF"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-20 13:26:07',
                'updated_at' => '2025-11-20 13:26:07',
