                'session_number' => 1,
            'title' => 'Q-Switch Toning + Hydrafacial Prep + Ultrasound Tranexamic Infusion (Brightening & Debrief)',
                'treatment_time' => '90 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Disinfect room surfaces; set up disposable headband, gauze, towels, and clean gloves.", "Review consent, confirm no recent peel/laser within 7 days, verify no photosensitizing meds or active infections.", "Confirm patient data: Age 62, sun exposure <1 hr, no allergies/pregnancy; remove nose ring/jewelry near treatment area.", "Prepare Hydrafacial Machine: attach Cutin Removal Spatula and Suction Probe tips; load Hydrafacial Serum AS1 and SA2.", "Set Q‑Switch Laser to 1064 nm long spot for low-fluence toning; keep eye shields, smoke evacuator, and wet gauze ready.", "Check cooling pack and soothing gel; keep sterile cotton, saline, and non-alcoholic degreaser available.", "Prepare Ultrasound Infusion Probe (face + ocular) with TRX A (Tranexamic Acid) and Hyaluronic Acid; keep PDRN vial for peri‑orbital infusion.", "Power on LED Light Therapy machine; select Red mode (primary) and Blue mode (localized).", "Keep Hydrate peel‑off mask and neutral water bowl ready; ensure timer availability for each step.", "Verify sunscreen (broad-spectrum SPF 50), hydrating serum, and barrier moisturizer for final application."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1-2 (Minimal to Mild)", "current_value": "4 - Marked"}, {"concern": "Visual Acne Grading", "target_value": "Grade 0 (Clear)", "current_value": "Grade 1"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0-1", "current_value": "Grade 2"}, {"concern": "Skin Hydration", "target_value": "0-1 (Excellent to Mild Dehydration)", "current_value": "2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "2-3 (Healthy to Radiant Glow)", "current_value": "0"}, {"concern": "Under-Eye Vascularity vs Structural Shadows", "target_value": "Score 0-1", "current_value": "Score 2 - Moderate"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Cleanse the entire face and neck with a gentle cleanser; rinse and pat dry. Degrease lightly with saline on gauze to ensure even laser energy absorption. Avoid rubbing under-eye skin.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Saline/degrea​ser"]}, {"duration": "6 mins", "how_to_do": "Perform light lymphatic drainage massage: effleurage strokes from mid-face to preauricular nodes and downward to supraclavicular nodes. Pressure should be gentle (no pinching). Stop if erythema increases or discomfort occurs.", "step_number": "2", "ingredients_equipments": ["Manual massage technique"]}, {"duration": "12 mins", "how_to_do": "Use the Cutin Removal Spatula for 1 pass per zone to lift superficial debris. Switch to Suction Probe with AS1 for face-wide cleanse/exfoliation at low vacuum (−18 to −22 kPa), slow overlapping passes. Use SA2 only on nose and central forehead for oil control. Perform gentle comedone extraction on the nose; avoid over-passes on dry cheeks. Rinse and pat dry.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine (Cutin Removal Spatula, Suction Probe/Bubble Pen)", "Hydrafacial Serum AS1", "Hydrafacial Serum SA2 (T‑zone only)"]}, {"duration": "3 mins", "how_to_do": "Place intra‑orbital metal eye shields after instilling lubricating drops if needed; cover brows/lips/moles with wet gauze. Confirm no reflective surfaces are exposed. Do a small test shot behind the ear to check tolerance.", "step_number": "4", "ingredients_equipments": ["Metal eye shields", "Wet gauze", "Smoke evacuator"]}, {"duration": "18 mins", "how_to_do": "Perform low‑fluence laser toning at 1064 nm, 6–8 Hz, energy 600–900 mJ (adjust to skin response). Use 6–8 mm spot size; deliver 2 light passes over cheeks, forehead, chin; 1–2 additional passes on darker macules. Maintain constant motion; endpoint is mild, transient erythema and subtle acoustic \'pop\' without frosting. Avoid direct peri‑orbital skin and any open lesions. Stop immediately if excessive whitening or discomfort develops.", "step_number": "5", "ingredients_equipments": ["Q‑Switch Laser (1064 nm)", "Cooling gel"]}, {"duration": "5 mins", "how_to_do": "Cool treated areas with cold compress to reduce heat and erythema. Do not rub. Proceed when skin temperature normalizes and erythema subsides.", "step_number": "6", "ingredients_equipments": ["Cold compress", "Thermal spring water spray"]}, {"duration": "10 mins", "how_to_do": "Apply TRX A mixed with Hyaluronic Acid as a thin film. Use Face Ultrasound Probe in circular motion at medium intensity for 6–8 minutes across pigmented zones. For under‑eye, switch to Ocular Probe with PDRN at low intensity; glide gently without pressure for 2–3 minutes per side. Stop if edema or stinging occurs.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid", "PDRN (for peri‑orbital)"]}, {"duration": "12 mins", "how_to_do": "Position LED panel 15–20 cm from face. Use Red mode for 10 minutes to calm post‑laser erythema and support collagen. Optionally switch to localized Blue mode for 2 minutes over the T‑zone to reduce P. acnes activity. Eyes protected at all times.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine (Red and Blue modes)"]}, {"duration": "10 mins", "how_to_do": "Apply Hydrate peel‑off mask evenly avoiding eyelids and nostrils; allow to set for 8–10 minutes. Remove in one piece; gently wipe residue with damp cotton.", "step_number": "9", "ingredients_equipments": ["Hydrate peel‑off mask"]}, {"duration": "9 mins", "how_to_do": "Finish with calming hydrating serum (non‑acidic), seal with moisturizer, then apply SPF 50 sunscreen generously. Provide strict post‑care: no scrubs/actives for 48–72 hours, reapply sunscreen every 3 hours daytime.", "step_number": "10", "ingredients_equipments": ["Brightening/Hydrating serum", "Barrier moisturizer", "Broad‑spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-25 12:31:13',
                'updated_at' => '2025-11-25 12:31:13',
            ),
            34 => 
            array (
                'id' => 35,
                'assessment_id' => 20,
