            'title' => 'HydraCleanse + Q-Switch Laser Toning + TXA/HA Infusion (Single-Session Focus)',
                'treatment_time' => '80 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize room surfaces; prepare fresh linens, headband, gauze, cotton, and disposable tips.", "Verify consent, confirm no allergies/pregnancy; reconfirm sun exposure <1 hr and no recent peels/actives in last 24 hrs.", "Remove makeup/sunscreen; take baseline photographs under white and brown light.", "Hydrafacial Machine: power on; select Suction/Bubble pen and Cutin Removal Spatula; load SA2 (T-zone) and A03 (Hydration) serums.", "Prepare sterile extractor, chilled saline, and cold compress for post-laser cooling.", "Q-Switch Laser: set to 1064 nm; test-spot area ready; ensure protective eye shields for patient and staff.", "Ultrasound Infusion Probe ready with TRX A (Tranexamic Acid) + Hyaluronic Acid solutions; keep Ocular probe for peri‑orbital.", "Choose Calming peel‑off mask and neutral water bowl; keep timer.", "Keep non-comedogenic finishing products: hydrating serum, moisturizer, and broad-spectrum SPF 50+.", "Maintain comfortable room temperature and adequate lighting; explain sensations and post-care to patient."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation", "target_value": "1 - Minimal / Almost Clear", "current_value": "4 - Marked"}, {"concern": "Texture + Open Pores", "target_value": "Grade 0 - Clear / Smooth", "current_value": "Grade 2"}, {"concern": "Skin Hydration", "target_value": "Score 0 - Excellent Hydration", "current_value": "Score 2"}, {"concern": "Skin Sebum Content / T-zone", "target_value": "Score 1 (Low-Normal Sebum)", "current_value": "Score 2"}, {"concern": "Comedonal Density", "target_value": "Score 0 - No Comedones", "current_value": "Score 1"}, {"concern": "Skin Luminosity / Glow", "target_value": "Score 2–3 (Healthy to Radiant)", "current_value": "Score 1"}, {"concern": "Skin Sensitivity / Redness", "target_value": "Score 0 - No Sensitivity", "current_value": "Score 1"}, {"concern": "Peri‑orbital Mild Darkness", "target_value": "None", "current_value": "Mild"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Cleanse face and neck thoroughly; massage for 2 minutes in circular motions. Wipe with damp gauze and tone to remove residue and excess oils. Check skin for active lesions; avoid any erosions during subsequent steps.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Gauze", "Toner"]}, {"duration": "10 mins", "how_to_do": "On damp skin use the Cutin Removal Spatula at low vibration; glide at 45° angle focusing on forehead, nose, and chin for keratin softening. Avoid overpressure on cheeks due to mild sensitivity. Stop when superficial debris is cleared with no erythema.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)"]}, {"duration": "12 mins", "how_to_do": "Use low–medium vacuum (start low on cheeks). Two gentle passes on T‑zone using SA2; one pass on cheeks using A03. Spiral strokes; keep tip moving to avoid petechiae. Focus on nose pores for 2–3 additional spot passes. Rinse with cool water after completion.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum SA2 (Oil Control)", "Hydrafacial Serum A03 (Hydration)"]}, {"duration": "5 mins", "how_to_do": "Only if required after Step 3, perform minimal manual extraction of residual comedones on nose using sterile loop; apply gentle pressure, not exceeding 2 attempts per pore. Dab chilled saline to calm area before moving on.", "step_number": "4", "ingredients_equipments": ["Sterile extractor", "Chilled saline"]}, {"duration": "6 mins", "how_to_do": "Perform manual lymphatic drainage massage: light effleurage from midface to pre‑auricular nodes, then to supraclavicular nodes. Keep pressure light; avoid freshly extracted zones. This reduces swelling and prepares skin for laser.", "step_number": "5", "ingredients_equipments": ["Massage cream or light gel"]}, {"duration": "15 mins", "how_to_do": "Apply eye shields. Perform test spot at mandibular area with 1064 nm, energy 700–900 mJ, frequency 6–8 Hz, 6–8 mm spot, single pass. If endpoint is mild immediate whitening with transient erythema and no discomfort, proceed to full face: 1–2 passes over pigmented regions (forehead, malar cheeks, nose), keep 10–20% overlap. Avoid direct pass over active acne or eyelids. Cool skin with cold air during procedure. Stop if excessive erythema or pain occurs.", "step_number": "6", "ingredients_equipments": ["Q-Switch Laser (1064 nm)", "Eye shields", "Cold air/cold compress"]}, {"duration": "8 mins", "how_to_do": "Apply TRX A mixed 1:1 with Hyaluronic Acid on treatment zones. Glide ultrasound probe with slow circular motions for 5 minutes on face (low intensity). Use ocular probe around under‑eye for 2–3 minutes, avoiding lash line. Purpose: calm post‑laser skin, improve hydration and pigmentation. Wipe excess gently.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid) solution", "Hyaluronic Acid solution", "Ocular Ultrasound Infusion Probe (peri‑orbital)"]}, {"duration": "10 mins", "how_to_do": "Apply an even layer avoiding nostrils and eyes. Leave for 8–10 minutes until mask fully sets. Peel off from edges; check for reduction in erythema and improved comfort.", "step_number": "8", "ingredients_equipments": ["Calming peel-off mask"]}, {"duration": "9 mins", "how_to_do": "Finishers per clinic rule: pat a hydrating serum until absorbed, seal with moisturizer, then apply SPF 50+ evenly. Educate patient to reapply sunscreen and avoid hot showers/scrubs for 48 hours.", "step_number": "9", "ingredients_equipments": ["Hydrating/brightening serum (non‑retinol)", "Ceramide-based moisturizer", "Broad-spectrum Sunscreen SPF50+"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-26 19:11:18',
                'updated_at' => '2025-11-26 19:11:18',
            ),
            35 => 
            array (
                'id' => 36,
                'assessment_id' => 21,
                'user_id' => 18,
                'plan_type' => 'single',
