            'title' => 'Brightening Hydrafacial + RF Tightening + LED (Event-safe single session)',
                'treatment_time' => '90',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize room and trolley; lay fresh linens, headband, and disposable sheets.", "Review consent, recent procedures, allergies, pregnancy status, anticoagulants; confirm upcoming travel and social event noted – avoid Q-Switch/medium–deep peels.", "Assess skin under white/UV light to map T‑zone porphyrins, pigmentation density, and sensitive areas.", "Set up Hydrafacial Machine: select Suction/Bubble pen, Cutin Removal Spatula, Face & Ocular Ultrasound Infusion Probes, Oxygen Spray.", "Prepare Hydrafacial solutions: SA2 (T‑zone oil control), AS1 (gentle cleanse for cheeks), Jet infusion vials TRX A (Tranexamic Acid) and Hyaluronic Acid; keep PDRN for peri‑orbital infusion.", "Set up Radio Frequency Machine with conductive gel; test handpiece temperature; start with energy 4–5 (adjust per comfort).", "Prepare LED Light Therapy (Red mode primary; optional Blue for T‑zone) and protective eye shields.", "Lay out peel‑off Brighten mask; cooling bowl and fan for comfort.", "Stock finishing products: repair serum, non‑comedogenic moisturizer, broad‑spectrum sunscreen SPF 50+, lip balm with SPF.", "Have waste bag, cotton, gauze, sterile comedone tips, neutral pH water, timer, and cold pack available."]',
                'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1 - Minimal / Almost Clear", "current_value": "4 - Marked"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0 - Clear / Smooth", "current_value": "Grade 2"}, {"concern": "Comedonal Density", "target_value": "0 - No Comedones", "current_value": "2"}, {"concern": "Skin Hydration", "target_value": "0 - Excellent Hydration", "current_value": "2"}, {"concern": "Skin Sebum Content", "target_value": "1 - Low-Normal Sebum", "current_value": "2"}, {"concern": "Superficial Wrinkles", "target_value": "Grade 1 - Very Mild", "current_value": "Grade 2"}, {"concern": "Jawline Sagging", "target_value": "Grade 1 - Very Mild", "current_value": "Grade 2"}, {"concern": "Under-Eye Vascularity vs Structural Shadows", "target_value": "Score 0 - None", "current_value": "Score 2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "3 - Radiant / Luminous Skin", "current_value": "1"}]',
            'steps' => '[{"duration": "5", "how_to_do": "Cleanse entire face and neck with gentle circular motions for 2–3 minutes; rinse and pat dry. Tone lightly to balance pH. Avoid aggressive rubbing over pigmented clusters and under‑eye area.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Gentle cleanser", "Toner"]}, {"duration": "6", "how_to_do": "Perform light manual lymphatic drainage: effleurage from mid‑face to pre‑auricular nodes and down to supraclavicular nodes; 6–8 strokes per line. Pressure should be light, avoiding dragging on peri‑orbital skin. Stop if dizziness or discomfort.", "step_number": "2", "ingredients_equipments": ["Hands (massage oil/gel)"]}, {"duration": "12", "how_to_do": "Use spatula at low to medium intensity for gentle exfoliation. Glide at 45° angle; one pass on cheeks/forehead, avoid over‑exfoliating pigmented patches. End when keratinous plugs are loosened and skin feels smooth without erythema.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine - Cutin Removal Spatula", "Hydrafacial Serum AS1 (Cleanse & Exfoliate)"]}, {"duration": "12", "how_to_do": "Perform comedone cleansing with two light passes over T‑zone (nose > medial cheeks) and one pass on the rest. Keep suction at low–moderate; maintain continuous glide to prevent petechiae. Focus where UV showed porphyrin clusters. Stop if excessive erythema or capillary fragility noted.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe/Bubble Pen", "Hydrafacial Serum SA2 (Oil Control)"]}, {"duration": "10", "how_to_do": "Mix TRX A with a few drops of HA; use ultrasound infusion in slow linear strokes. 3–4 minutes per hemiface, 2 minutes on forehead, 1–2 minutes perioral. Keep probe moving to avoid hot spots. Avoid open lesions. End when product is absorbed and mild glow appears.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine - Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid"]}, {"duration": "6", "how_to_do": "For under‑eyes, apply PDRN+HA cocktail; gently sweep from inner canthus to lateral canthus without pressing on the globe. 2–3 minutes each eye. Indicated for moderate peri‑orbital hollowness and vascular show; stop if tearing or discomfort occurs.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "PDRN", "Hyaluronic Acid"]}, {"duration": "12", "how_to_do": "Lower‑face and jawline tightening. Energy level 4–6 depending on tolerance. Use small circular motions, 2 passes per zone (lower cheek, jowl, sub‑mandibular). Target skin temp ~40–41°C; keep probe moving to avoid burns. Avoid thyroid and bony prominences for prolonged contact.", "step_number": "7", "ingredients_equipments": ["Radio frequency Machine", "Conductive gel"]}, {"duration": "8", "how_to_do": "Apply a thin, even layer avoiding eyes and nostrils. Leave for 6–8 minutes for cooling and pigment‑brightening support. Remove in one sheet from edges; wipe residuals gently.", "step_number": "8", "ingredients_equipments": ["Peel‑off Mask: Brighten"]}, {"duration": "10", "how_to_do": "Protect eyes. Use Red LED for 8–10 minutes over full face to reduce erythema and support barrier repair. If comedonal T‑zone persists, switch to Blue LED for last 2 minutes focused on nose/medial cheeks. Contraindication: photosensitivity disorders.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine (Red mode primary; optional Blue for T‑zone)", "Eye shields"]}, {"duration": "4", "how_to_do": "Deliver a fine oxygen mist in sweeping motions for 3–4 minutes to enhance immediate radiance and comfort. Keep nozzle 8–10 cm from skin; avoid eyes.", "step_number": "10", "ingredients_equipments": ["Hydrafacial Oxygen Injection (Hydra spray)"]}, {"duration": "5", "how_to_do": "Finish every treatment with Serum + Moisturizer + Sunscreen as mandated. Apply barrier‑support serum, follow with moisturizer. Apply SPF 50+ liberally (2 mg/cm²) and lip balm with SPF. Provide strict post‑care: avoid heat/sauna for 24h and diligent sun protection.", "step_number": "11", "ingredients_equipments": ["Repair serum (barrier‑support, non‑fragrant)", "Moisturizer (non‑comedogenic)", "Broad‑spectrum Sunscreen SPF 50+", "SPF lip balm"]}]',
                'status' => 'pending',
