            36 => 
            array (
                'id' => 37,
                'assessment_id' => 22,
                'user_id' => 19,
                'plan_type' => 'single',
                'session_number' => 1,
                'title' => 'Single-Session Clarify + Hydrate + Tighten Protocol',
                'treatment_time' => '90 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize room surfaces; set fresh disposable headband, towels, gauze, and gloves.", "Verify patient identity, obtain consent, review allergies/medications; confirm no recent peels/lasers.", "Assess beard area and cover with drape to avoid suction tugging on facial hair.", "Power on Hydrafacial Machine; prime Suction Probe/Bubble Pen and Cutin Removal Spatula; load AS1, SA2, and A03 solutions.", "Prepare Face Ultrasound Infusion Probe and Ocular Ultrasound Probe; keep conductive gel ready.", "Prepare serums for infusion: TRX A (Tranexamic Acid), Hyaluronic Acid, and PDRN in sterile cups.", "Set up Radio frequency Machine; test handpiece; preset energy 4–6 with contact gel available.", "Set LED Light Therapy Machine; ensure eye shields are available and cleaned.", "Select Peel-Off Mask: Brighten or Hydrate based on skin feel post-HF; keep spatula and bowl ready.", "Arrange finishing products: repair serum, non-comedogenic moisturizer, and broad-spectrum SPF 50.", "Check emergency kit, cold pack, and fan for comfort; maintain room temperature 22–24°C.", "Explain post-care and obtain verbal confirmation to proceed."]',
                'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1 - Minimal / Almost Clear", "current_value": "3 - Moderate"}, {"concern": "Visual Acne Grading", "target_value": "Grade 0 - Clear", "current_value": "Grade 1"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0-1", "current_value": "Grade 2"}, {"concern": "Skin Hydration", "target_value": "0-1", "current_value": "2"}, {"concern": "Skin Sebum Content", "target_value": "1", "current_value": "2"}, {"concern": "Barrier Health", "target_value": "0-1", "current_value": "2"}, {"concern": "PeriOrbital Health", "target_value": "Mild / None", "current_value": "Moderate"}, {"concern": "Vascularity / Redness Profiling", "target_value": "0", "current_value": "1"}, {"concern": "Jawline Sagging", "target_value": "Grade 1", "current_value": "Grade 2"}, {"concern": "Superficial Wrinkles", "target_value": "Grade 1", "current_value": "Grade 2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "2-3", "current_value": "1"}, {"concern": "Comedonal Density", "target_value": "0-1", "current_value": "2"}, {"concern": "Texture Irregularities Beyond Pores", "target_value": "0-1", "current_value": "2"}, {"concern": "Regional Oil Distribution", "target_value": "0", "current_value": "1"}, {"concern": "Lip Pigmentation", "target_value": "Absent", "current_value": "Present"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Cleanse face and neck thoroughly using a gentle cleanser; massage in circular motions for 2 minutes focusing on T-zone and beard line; rinse and pat dry. Degrease with alcohol-free toner. Ensure skin is fully dry before device contact.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Toner"]}, {"duration": "5 mins", "how_to_do": "Perform light lymphatic drainage massage from center to preauricular nodes and down to supraclavicular fossa to reduce puffiness and improve circulation. Avoid excessive pressure on peri‑orbital area. Proceed when skin is relaxed and warm.", "step_number": "2", "ingredients_equipments": ["Manual massage (no device)"]}, {"duration": "7 mins", "how_to_do": "Using the Hydrafacial Cutin Removal Spatula, perform a single uniform pass with AS1 over full face for cleanse/exfoliation. Keep suction low (level 1–2), glide slowly without pausing on one spot. Avoid broken skin. End when skin feels smooth with no visible irritation.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)", "Hydrafacial Serum AS1"]}, {"duration": "6 mins", "how_to_do": "Focus on T‑zone: nose, forehead, chin. Perform 1–2 passes with SA2 at low–medium suction (level 2–3). Keep tip moving to prevent petechiae. Stop if significant erythema develops.", "step_number": "4", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe / Bubble Pen", "Hydrafacial Serum SA2 (Oil Control)"]}, {"duration": "6 mins", "how_to_do": "Target comedone extraction on nose and medial cheeks with short overlapping strokes. Maintain suction at level 2. Do not overwork any single pore; limit to 2 passes per zone. Wipe residue and reassess congestion.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe / Bubble Pen"]}, {"duration": "3 mins", "how_to_do": "Hydra-spray A03 evenly across face from 10–15 cm distance for 2–3 cycles to rehydrate and soothe after extractions. Blot excess moisture before the next step.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine - Oxygen Injection (Hydra spray)", "Hydrafacial Serum A03 (Hydration)"]}, {"duration": "8 mins", "how_to_do": "Mix TRX A + Hyaluronic Acid + PDRN (1:1:1). Apply thin layer and use Face Ultrasound Infusion Probe with medium intensity, slow circular strokes for 8 minutes, emphasizing cheeks, nose and forehead. Keep constant movement; reapply gel if drag occurs. Discontinue if excessive heat or irritation appears.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid", "PDRN (polydeoxyribonucleotide)"]}, {"duration": "5 mins", "how_to_do": "Treat peri‑orbital area using ocular probe on low intensity. Glide from inner to outer canthus, avoiding direct contact with eyelid margin. 2–3 gentle passes per eye to infuse diluted TRX A with PDRN for vascular-pigment improvement and repair. Stop if patient reports buzzing or discomfort.", "step_number": "8", "ingredients_equipments": ["Ocular Ultrasound Infusion Probe", "TRX A (diluted 50%)", "PDRN"]}, {"duration": "16 mins", "how_to_do": "Apply contact gel along jawline and lower cheeks. Use RF energy 4–6 with continuous circular strokes. Two passes per side aiming for skin temperature ~40–42°C without hot spots (8 mins each side). Keep handpiece moving; avoid thyroid and adam’s apple. Stop if excessive heat or erythema persists.", "step_number": "9", "ingredients_equipments": ["Radio frequency Machine", "Contact gel"]}, {"duration": "15 mins", "how_to_do": "Place eye shields. Use Red mode for 10 minutes (collagen stimulation, reduce redness) followed by Blue mode for 5 minutes (reduce acne bacteria). Keep device at manufacturer’s recommended distance. End if patient reports photosensitivity or heat discomfort.", "step_number": "10", "ingredients_equipments": ["LED Light Therapy Machine", "Eye shields"]}, {"duration": "10 mins", "how_to_do": "Select Brighten for pigmentation focus or Hydrate if skin feels tight. Apply evenly avoiding hairline and brows. Leave for 8–10 minutes until set; peel gently from edges. Wipe residues with damp gauze.", "step_number": "11", "ingredients_equipments": ["PeelOffMask: Brighten or Hydrate"]}, {"duration": "3 mins", "how_to_do": "Finish every treatment by applying serum over face and under-eye, then seal with moisturizer. Apply SPF 50 generously to full face and neck. Provide post-care instructions: avoid hot water, gym, or sun exposure for 24 hours.", "step_number": "12", "ingredients_equipments": ["Repair serum (Hyaluronic/PDRN blend)", "Moisturizer (non-comedogenic)", "Broad-spectrum Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-27 17:21:10',
                'updated_at' => '2025-11-27 17:21:10',
            ),
