            'title' => 'Event-Ready Clarifying Hydraglow (Hydrafacial + Jet Infusion + RF Contour + LED)',
                'treatment_time' => '85 mins',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Sanitize room and treatment bed; arrange disposable headband, towels, tissues, gloves, and fresh tips/probes.", "Verify consent, allergies, recent procedures; confirm no pregnancy/breastfeeding and social event within 7 days (avoid Q-Switch & deep peels).", "Cleanse patient face to remove makeup and oils; protect hairline with cap.", "Prepare Hydrafacial Machine: prime Suction Probe/Bubble Pen; ready Cutin Removal Spatula; load serums AS1 (normal), SA2 (oil control), A03 (hydration).", "Prepare ultrasound infusion solutions: TRX A (Tranexamic Acid), Hyaluronic Acid, and PDRN; decant into sterile cups for single-use.", "Set Radio frequency Machine to low–moderate energy (3–5) for face/jawline; check grounding and ensure no metal jewelry.", "Ready LED Light Therapy Machine; disinfect panel; set Blue then Red sequence; place eye shields.", "Choose Hydrate peel-off mask; keep mixing bowl/spatula; ensure no aloe or vitamin C allergy if using adjunct serums.", "Keep neutral saline, cotton, cold pack, and calming gel for any sensitivity; maintain room temperature cool.", "Prepare finishing products: barrier-repair serum, non-comedogenic moisturizer, and SPF 50 sunscreen."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation Score", "target_value": "1-2 (Minimal to Mild)", "current_value": "3 - Moderate"}, {"concern": "Visual Acne Grading", "target_value": "Grade 0-1", "current_value": "Grade 2"}, {"concern": "Texture + Open Pores Grading", "target_value": "Grade 0-1", "current_value": "Grade 2"}, {"concern": "Skin Hydration", "target_value": "0-1 (Excellent to Mild Dehydration)", "current_value": "2"}, {"concern": "Skin Sebum Content", "target_value": "1 (Low-Normal Sebum)", "current_value": "2"}, {"concern": "Skin Sensitivity Scoring", "target_value": "0 (No Sensitivity)", "current_value": "1"}, {"concern": "Barrier Health", "target_value": "0 (Strong / Healthy Barrier)", "current_value": "1"}, {"concern": "PeriOrbital Health", "target_value": "None to Mild", "current_value": "Moderate"}, {"concern": "Under-Eye Vascularity vs Structural Shadows", "target_value": "Score 0-1", "current_value": "Score 2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "2-3 (Healthy to Radiant Glow)", "current_value": "1"}, {"concern": "Comedonal Density", "target_value": "0-1", "current_value": "2"}, {"concern": "Texture Irregularities Beyond Pores", "target_value": "0-1", "current_value": "2"}, {"concern": "Regional Oil Distribution", "target_value": "0 (Even / Balanced)", "current_value": "1"}]',
            'steps' => '[{"duration": "5 mins", "how_to_do": "Cleanse the entire face and neck with a gentle cleanser using circular motions for 2 minutes; remove with damp gauze; tone lightly to degrease. Check skin for any open lesions. Proceed only if no contraindications.", "step_number": "1", "ingredients_equipments": ["Gentle cleanser", "Gauze", "Toner"]}, {"duration": "10 mins", "how_to_do": "Perform uniform exfoliation pass with the Cutin Removal Spatula on low setting; glide along forehead, cheeks, nose, and chin with light pressure; use AS1 to loosen debris. Avoid overpasses on sensitive peri‑oral/under-eye areas. Stop when mild pinkness appears.", "step_number": "2", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)", "Hydrafacial Serum AS1 (Cleanse & Exfoliate)"]}, {"duration": "12 mins", "how_to_do": "Targeted T‑zone decongestion: use SA2 with 2–3 passes on nose and central forehead with continuous suction; slow spiral motions over comedones. Use A03 on cheeks with 1–2 gentle passes to avoid overdrying. Wipe residue and check for comfort; avoid repeated passes on erythematous spots.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum SA2 (Oil Control)", "Hydrafacial Serum A03 (Hydration)"]}, {"duration": "5 mins", "how_to_do": "Perform lymphatic drainage massage: light effleurage from mid‑face to preauricular nodes, then down to supraclavicular points. Use the Ice Probe briefly to calm flushed areas if needed. Stop if excessive redness or discomfort occurs.", "step_number": "4", "ingredients_equipments": ["Manual technique", "Hydrafacial Ice Probe (optional)"]}, {"duration": "8 mins", "how_to_do": "Apply a thin layer of TRX A mixed 1:1 with Hyaluronic Acid; use the Face Ultrasound Infusion Probe at low–medium intensity to infuse over forehead, cheeks, and upper lip for 6 minutes. Finish with 2 minutes of PDRN infusion on cheeks for barrier repair. Keep probe moving; avoid thyroid and eyelids.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Face Ultrasound Infusion Probe", "TRX A (Tranexamic Acid) solution", "Hyaluronic Acid", "PDRN"]}, {"duration": "6 mins", "how_to_do": "For under‑eye area, use ocular probe with diluted TRX A + HA; glide from inner to outer canthus without pressure for 3 minutes each side to improve pigmentation and hydration. Avoid direct contact with the lash line; stop if tearing or burning occurs.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Ocular Ultrasound Infusion Probe", "Diluted TRX A + Hyaluronic Acid"]}, {"duration": "15 mins", "how_to_do": "Apply conductive gel along jawline and lower cheeks. Use RF at energy 3–5 with slow circular strokes; 7–8 minutes per side. Maintain constant motion to prevent hotspots; aim for mild warmth only. Contraindicated in metal implants/pacemakers—confirm before starting.", "step_number": "7", "ingredients_equipments": ["Radio frequency Machine"]}, {"duration": "12 mins", "how_to_do": "Place protective eye shields. Use Blue light for 5 minutes across the face to reduce P. acnes activity, then switch to Red light for 7 minutes to calm inflammation and boost repair. Keep panel 10–15 cm from skin; discontinue if heat discomfort occurs.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine"]}, {"duration": "10 mins", "how_to_do": "Mix Hydrate mask to a smooth paste; apply evenly avoiding nostrils and eyes; allow to set for 8–10 minutes for occlusive hydration and soothing. Peel off gently from edges; wipe residues with damp sponge.", "step_number": "9", "ingredients_equipments": ["Hydrate Peel-off Mask"]}, {"duration": "2 mins", "how_to_do": "Finish with a thin layer of serum, then moisturizer. Apply broad-spectrum SPF 50 generously to all treated areas. Provide post-care: avoid heat, gym, and makeup for 12 hours; reapply SPF.", "step_number": "10", "ingredients_equipments": ["Barrier-repair serum (e.g., Hyaluronic/PDRN)", "Moisturizer (non-comedogenic)", "Sunscreen SPF 50"]}]',
                'status' => 'pending',
                'created_at' => '2025-11-28 15:29:12',
                'updated_at' => '2025-11-28 15:29:12',
