            38 => 
            array (
                'id' => 39,
                'assessment_id' => 29,
                'user_id' => 16,
                'plan_type' => 'single',
                'session_number' => 1,
                'title' => 'Hydrafacial Deep Cleanse + Comedone Control + Hydration, Brightening and LED',
                'treatment_time' => '70 minutes',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Review history: no allergies, no photosensitizing meds; obtain consent.", "Set Hydrafacial Machine: load Serums SA2 (oil control), AS1 (cleanse/exfoliate), A03 (hydration). Prepare Suction Probe/Bubble Pen, Cutin Removal Spatula, Oxygen Injection, Ocular & Face Ultrasound Probes.", "Prepare High-Frequency Machine with mushroom electrode; test spark at low setting.", "Lay out Jet Infusion solutions: Hyaluronic Acid, TRX A (Tranexamic Acid), PDRN (optional for peri-orbital).", "Keep Chemical Peel: Gel Based Mandelic Peel with fan brush; neutralization with distilled water/gauze ready.", "Masks: Charcoal peel-off for T‑zone and Hydrate peel-off for cheeks/under‑eye; applicator brushes ready.", "Consumables: Extraction tools (loop/comedone), cotton/gauze, alcohol swabs, hydrating gel base, distilled water, cleansing towels, disposable headband.", "LED Light Therapy Machine: preselect Blue (anti-bacterial) 12 min and Red (anti-inflammatory) 8 min; eye shields ready.", "Room setup: reclining chair, bright task light, waste container; maintain asepsis.", "Explain safety signals: pain >5/10, excessive erythema, ooze—pause and reassess."]',
            'concerns_addressed' => '[{"concern": "Skin Hydration Score", "target_value": "3", "current_value": "2"}, {"concern": "Visual Acne Grading (v5.1 Spatial)", "target_value": "1", "current_value": "2"}, {"concern": "Skin Sebum Index (v6.0)", "target_value": "2", "current_value": "3"}, {"concern": "Superficial Pigmentation Scoring", "target_value": "2", "current_value": "3"}, {"concern": "Texture & Open Pores Score", "target_value": "2", "current_value": "3"}, {"concern": "Vascularity / Redness Scoring (v6)", "target_value": "1", "current_value": "2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "3", "current_value": "2"}, {"concern": "Peri-Orbital Health Score", "target_value": "2", "current_value": "3"}, {"concern": "Textural Radiance Index", "target_value": "2", "current_value": "3"}]',
            'steps' => '[{"duration": "4 minutes", "how_to_do": "Pre-cleanse with AS1 using Hydrafacial suction on low vacuum (0.8–1.0). One slow pass per zone from medial to lateral; keep probe perpendicular with light glide to avoid erythema. Pat dry.", "step_number": "1", "ingredients_equipments": ["Cleansing Towels", "Hydrafacial Serum AS1", "Hydrafacial Machine - Suction Probe"]}, {"duration": "5 minutes", "how_to_do": "Perform neck-first drainage: 6 gentle pumps at supraclavicular nodes, then along sternocleidomastoid to pre‑auricular nodes. Face: glide from mid‑face to parotid nodes and from infraorbital to temples with feather-light pressure. Purpose: reduce peri‑orbital edema and prep skin.", "step_number": "2", "ingredients_equipments": ["Manual Lymphatic Drainage (hands with hydrating gel base)"]}, {"duration": "7 minutes", "how_to_do": "Exfoliation & decongestion. T‑zone: SA2, 2 slow passes (vacuum 1.5–1.8); Cheeks/forehead periphery: AS1, 1–2 passes (vacuum 1.2–1.4). Keep 2–3 cm/s glide speed; overlap 10%. Stop if diffuse erythema > grade 2.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine - Cutin Removal Spatula", "Hydrafacial Serum SA2", "Hydrafacial Serum AS1"]}, {"duration": "5 minutes", "how_to_do": "Apply a thin, even layer—start cheeks, then forehead, nose, chin; avoid immediate beard nicks. Contact time: 2 minutes cheeks/forehead, 3 minutes nose (comedones). Fan cool air; watch for intense stinging or whitening. Neutralize thoroughly with distilled water-soaked gauze.", "step_number": "4", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan Brush", "Distilled Water", "Gauze Pads"]}, {"duration": "9 minutes", "how_to_do": "Targeted comedone clearance. Start nose: vertical lanes from alar base to tip with vacuum 1.8–2.0; 2 passes. Manual loop extraction for resistant open comedones—apply gentle downward-and-lateral pressure at 30–45°; limit to 3 attempts per lesion. Move to medial cheeks and chin with vacuum 1.4–1.6. Clean each site with alcohol swab.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine - Suction Probe/Bubble Pen", "Extraction Tools (Loop/Manual Comedone Extractor)", "Alcohol Swabs"]}, {"duration": "3 minutes", "how_to_do": "Post-extraction sanitation. Place gauze for slip; low intensity. Hover 0.3–0.5 cm above skin making small circular motions over T‑zone for 2 minutes; quick sparks only on residual papules. Stop if warmth becomes uncomfortable.", "step_number": "6", "ingredients_equipments": ["High-Frequency Machine (mushroom electrode)"]}, {"duration": "6 minutes", "how_to_do": "Oxy‑infuse actives. Mix TRX A for malar/forehead (2 passes at 12–15 cm, slow sweeping arcs). Follow with Hyaluronic Acid across entire face including beard area (2 passes) to restore hydration and barrier.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine - Oxygen Injection (Hydra spray)", "TRX A (Tranexamic Acid)", "Hyaluronic Acid"]}, {"duration": "4 minutes", "how_to_do": "Peri‑orbital infusion for edema and fine lines. Apply gel; set probe to low power. Glide from inner canthus to lateral canthus with gentle lifting angle 20–30°, then from upper cheek to infraorbital rim (U‑shaped strokes). 2 minutes per eye. Avoid direct globe pressure.", "step_number": "8", "ingredients_equipments": ["Hydrafacial Machine - Ocular Ultrasound Infusion Probe", "PDRN or Hyaluronic Acid", "pH Neutral Gel"]}, {"duration": "20 minutes", "how_to_do": "Blue LED first (anti‑bacterial): 12 minutes, face 10–15 cm from panel; ensure eye shields. Then Red LED (anti‑inflammatory/repair): 8 minutes, same distance. Assess warmth; stop if skin becomes very hot or erythema > grade 2.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine (Blue & Red)", "Eye Shields"]}, {"duration": "8 minutes", "how_to_do": "Multi-masking. Apply Charcoal mask on nose, central forehead, and chin (oil control). Apply Hydrate mask on cheeks and peri‑orbital upper cheek junction. Leave 8 minutes; remove in upward peel motion from edges.", "step_number": "10", "ingredients_equipments": ["Charcoal Peel-Off Mask", "Hydrate Peel-Off Mask", "Mask Applicator Brush"]}, {"duration": "4 minutes", "how_to_do": "If time permits, do a quick ultrasound infusion of Hyaluronic Acid for 1 minute per cheek, 1 minute shared across T‑zone—slow linear strokes, minimal pressure to enhance hydration without heat.", "step_number": "11", "ingredients_equipments": ["Face Ultrasound Infusion Probe (optional quick pass)", "Hyaluronic Acid"]}, {"duration": "5 minutes", "how_to_do": "Mandatory finish. Apply HA serum (pea‑size per zone) with upward strokes; seal with hydrating gel moisturizer. After full absorption, apply sunscreen generously (2 fingers rule) to face and peri‑orbital upper cheek; educate patient on reapplication.", "step_number": "12", "ingredients_equipments": ["Hyaluronic Acid serum", "Hydrating Gel Base (moisturizer)", "Broad-Spectrum Sunscreen SPF50+"]}]',
                'status' => 'pending',
                'created_at' => '2025-12-04 17:37:34',
                'updated_at' => '2025-12-04 17:37:34',
            ),
            39 => 
            array (
                'id' => 40,
                'assessment_id' => 35,
                'user_id' => 21,
                'plan_type' => 'single',
                'session_number' => 1,
            'title' => 'Hydra-Bright Repair + RF Tightening (Vitamin C–free, event-safe)',
                'treatment_time' => '70 minutes',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Confirm Vitamin C allergy; exclude all Vitamin C serums/peels/IV.", "Avoid Q-Switch Laser and all deep peels due to upcoming social event.", "Sanitize room; set temperature to 22–24°C; dim lights for LED readiness.", "Prepare Hydrafacial Machine: Suction Probe low-to-medium, Ice Probe, Face & Ocular Ultrasound Infusion Probes, Oxygen Injection.", "Lay out chemical peel: Gel Based Mandelic Peel; pH-neutral water for removal; fan ready.", "Jet infusion solutions: Hyaluronic Acid, TRX A (Tranexamic Acid), PDRN; Exclude Vitamin C.", "RF Machine preload: energy 4–6 (moderate), continuous mode with pH neutral gel.", "LED Light Therapy: Red + Green modes; patient and therapist eye protection.", "Masks: Peel-off Hydrate + Brighten; hydrogel under-eye pads; lip SPF balm.", "Consumables: Gauze, cotton pads, alcohol swabs, distilled water, hydrating gel base, fan brush, mask applicator.", "Emergency kit and post-care sunscreen SPF50 ready.", "Obtain consent; check for active infections/wounds; remove jewelry near treatment zones."]',
            'concerns_addressed' => '[{"concern": "Superficial Pigmentation Scoring", "target_value": "3", "current_value": "4"}, {"concern": "Peri-Orbital Health Score", "target_value": "3", "current_value": "4"}, {"concern": "Jawline Sagging Score", "target_value": "4", "current_value": "4"}, {"concern": "Skin Hydration Score", "target_value": "3-4", "current_value": "2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "3", "current_value": "2"}, {"concern": "Barrier Health + Sensitivity (Combined Score)", "target_value": "2", "current_value": "3"}, {"concern": "Texture & Open Pores Score", "target_value": "2-3", "current_value": "3"}, {"concern": "Skin Sebum Index", "target_value": "2-3", "current_value": "2"}, {"concern": "Superficial Wrinkles Score", "target_value": "2-3", "current_value": "3"}, {"concern": "Lip Pigmentation Score", "target_value": "2-3", "current_value": "3"}]',
            'steps' => '[{"duration": "3 minutes", "how_to_do": "Seat patient comfortably. Perform gentle double cleanse with lukewarm distilled water; pat dry. Inspect skin for contraindications (open lesions, active infections).", "step_number": "1", "ingredients_equipments": ["Cleansing Towels", "Distilled Water"]}, {"duration": "6 minutes", "how_to_do": "Lymphatic drainage massage: use feather-light pressure. Strokes from mid-forehead → temples → pre-auricular nodes, then nose sidewalls → ears, malar region sweeping to parotid nodes, perioral → submandibular nodes, and finally submental sweeps to lateral neck. 6–8 repetitions each; avoid excessive pressure around the eyes.", "step_number": "2", "ingredients_equipments": ["Manual (hands + light cream/oil)", "Lymphatic drainage technique"]}, {"duration": "8 minutes", "how_to_do": "Hydrafacial gentle exfoliation: Set vacuum to low on cheeks/under-eye junction and medium on T-zone. Use AS1 on T-zone for 1 pass; use A03 for cheeks and peri-oral for 1–2 passes. Keep the tip moving; no dwelling >2 seconds per spot. Stop if pinpoint erythema or discomfort >5/10.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum AS1", "Hydrafacial Serum A03"]}, {"duration": "4 minutes", "how_to_do": "Apply Mandelic Peel thinly: forehead → cheeks → nose → chin, avoiding eyelids and corners of nose/lips. Contact time 2–3 minutes (event-safe). Fan patient; observe for intense erythema or frosting—if seen, remove immediately. Neutralize with cool distilled water and gauze.", "step_number": "4", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan Brush", "Distilled Water", "Gauze Pads"]}, {"duration": "4 minutes", "how_to_do": "Targeted comedone clearance on nose only: 1 pass with low-medium suction. Angle the tip at 45° and lift off between strokes to avoid petechiae. Stop when skin blanches or patient discomfort rises.", "step_number": "5", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen"]}, {"duration": "10 minutes", "how_to_do": "Mix HA + PDRN (1:1) for whole face infusion using ultrasound probe; slow circular motions, 2 passes per zone. Then spot‑infuse TRX A (thin layer under gel) over malar and upper lip for pigmentation—keep probe constantly moving, 1–2 minutes per cheek. Use Ocular probe: dilute TRX A + PDRN (1:1 with gel), glide from inner to outer canthus along infraorbital hollow with minimal pressure for 3 minutes each eye. Finish with oxygen spray to enhance absorption.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Oxygen Injection (Hydra spray)", "Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "Hyaluronic Acid (jet infusion solution)", "TRX A (Tranexamic Acid)", "PDRN", "Hydrating Gel Base"]}, {"duration": "9 minutes", "how_to_do": "Lower-face/jawline tightening: Apply gel. RF energy 4–6. Use slow upward lifting strokes from mandibular border to zygoma at 30–45° angle; 2 passes per side (3–4 minutes per side). Submental: horizontal passes from midline to each angle of mandible, 2 passes. Maintain continuous motion; target skin temp ~40–41°C; stop if excessive heat or erythema persists >60 seconds.", "step_number": "7", "ingredients_equipments": ["Radio Frequency Machine", "pH Neutral Gel (for RF, Ultrasound)"]}, {"duration": "13 minutes", "how_to_do": "Apply goggles. LED Red mode for 8 minutes (collagen support, barrier calming). Switch to Green mode for 5 minutes (pigment modulation). Keep face 15–20 cm from panel. Monitor for heat discomfort.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine", "Protective goggles"]}, {"duration": "10 minutes", "how_to_do": "Blend Hydrate + Brighten masks (Vitamin C–free). Apply an even layer to face and neck; place hydrogel under‑eye pads. Leave for 8–10 minutes until set; remove in one piece from edges upward. Wipe residue gently.", "step_number": "9", "ingredients_equipments": ["Peel-off Mask: Hydrate", "Peel-off Mask: Brighten", "Mask Applicator Brush", "Hydrating Gel Base"]}, {"duration": "3 minutes", "how_to_do": "Lip pigmentation care: Apply a thin film of TRX A mixed with gel to upper and lower lips for 1 minute massage; blot excess and apply SPF lip balm.", "step_number": "10", "ingredients_equipments": ["TRX A (Tranexamic Acid)", "Hydrating Gel Base", "Lip SPF Balm"]}, {"duration": "4 minutes", "how_to_do": "Finishers—mandatory: Apply serum evenly (face + neck), follow with ceramide/emollient moisturizer to seal barrier, and finally broad-spectrum sunscreen SPF50. Reapply lip SPF.", "step_number": "11", "ingredients_equipments": ["Serum (PDRN or HA)", "Moisturizer (ceramide-emollient)", "Sunscreen SPF50 PA+++ (broad spectrum)"]}]',
