            'title' => 'HydraClarify + Calm (T‑zone decongestion, hydration boost, barrier repair)',
                'treatment_time' => '75 minutes',
                'week' => 1,
            'preparations_checklist_for_therapist' => '["Confirm history, allergies, and last-night actives; no retinoids/strong acids used.", "Obtain consent; capture standardized pre-treatment photos.", "Room: bright, clean; LED machine warmed; High-Frequency and Hydrafacial machines tested.", "Set Hydrafacial machine: load SA2 (Oil Control) cartridge for T‑zone and AS1/A03 for cheeks; check suction to low–medium.", "Prepare Gel Based Mandelic Peel (self-neutralizing) with fan brush; keep cool distilled water and gauze for comfort.", "Lay out extraction tools (loop extractor, gauze, alcohol swabs); sterilize tips.", "Prepare jet/infusion solutions: Hyaluronic Acid, TRX A (Tranexamic Acid), PDRN; ultrasound gel ready.", "Fit protective eye shields for LED and High-Frequency; ensure patient’s metal accessories removed.", "Preload LED: Blue mode 8 min, Red mode 6 min.", "Mask station: Hydrate peel-off mask; cooling bowl and spatula.", "Finishers ready: Hyaluronic Acid serum, Hydrating Gel Base moisturizer, Broad-spectrum sunscreen SPF50.", "Set up fresh linens, headband; ensure patient comfort and explain stop signals (burning, sharp pain, dizziness)."]',
            'concerns_addressed' => '[{"concern": "Barrier Health + Sensitivity (Combined Score)", "target_value": "1", "current_value": "2"}, {"concern": "Skin Hydration Score", "target_value": "4", "current_value": "3"}, {"concern": "Skin Sebum Index (v6.0)", "target_value": "2", "current_value": "3"}, {"concern": "Visual Acne Grading (v5.1 Spatial)", "target_value": "1", "current_value": "2"}, {"concern": "Texture & Open Pores Score", "target_value": "1", "current_value": "2"}, {"concern": "Vascularity / Redness Scoring (v6)", "target_value": "1", "current_value": "2"}, {"concern": "Superficial Pigmentation Scoring", "target_value": "2", "current_value": "2"}, {"concern": "Peri-Orbital Health Score", "target_value": "1", "current_value": "2"}, {"concern": "Lip Pigmentation Score", "target_value": "2", "current_value": "2"}, {"concern": "Textual Radiance Index", "target_value": "1", "current_value": "2"}]',
            'steps' => '[{"duration": "5 minutes", "how_to_do": "Seat patient semi-reclined. Wipe face with warm distilled water using cleansing towels. Begin Hydrafacial AS1 pre-cleanse: single pass over entire face with low suction (setting 1–2). Glide tip at 30–45° angle following lymph flow from midline outward. Avoid dragging around peri-ocular and recent breakouts.", "step_number": "1", "ingredients_equipments": ["Cleansing Towels", "Distilled Water", "Hydrafacial Machine (Suction Probe / Bubble Pen)", "Hydrafacial Serum AS1"]}, {"duration": "7 minutes", "how_to_do": "Perform manual lymphatic drainage. Sequence: supraclavicular pump (10 gentle presses each side), posterior auricular sweeps, then from chin to pre-auricular nodes with feather-light strokes. Forehead strokes from glabella to temples. Maintain pressure <30 mmHg. Stop if dizziness or discomfort occurs.", "step_number": "2", "ingredients_equipments": ["Hands (manual)", "Light Oil-free massage medium"]}, {"duration": "12 minutes", "how_to_do": "Zone-customized exfoliation-extraction. T‑zone (forehead center, nose, chin): use SA2 with medium suction (2–3), 2 cross-hatched passes; keep tip at 45° with slow linear strokes; hover briefly over visible comedones (1–2 seconds). Cheeks and peri-oral: switch to A03 with low suction (1–2), single even pass to protect barrier. Wipe residue with gauze.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum SA2 (Oil Control)", "Hydrafacial Serum A03 (Hydration)"]}, {"duration": "4 minutes", "how_to_do": "Apply a thin, even layer of Gel Based Mandelic Peel (self-neutralizing) from forehead to chin, avoid eye/nasal folds. Contact time 3–4 minutes (cheeks 2–3 if sensitive). Observe for uniform erythema/tingle; stop if sharp burning—remove immediately with cool wet gauze.", "step_number": "4", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan Brush", "Gauze Pads", "Distilled Water"]}, {"duration": "10 minutes", "how_to_do": "Targeted extractions mainly on nose and chin. Stretch skin with gauze; place loop perpendicular (90°) over comedone and press gently to express. Limit to 3 attempts per pore. Avoid inflamed lesions. After each cluster, dab with alcohol swab. Stop if capillary ooze or patient discomfort >5/10.", "step_number": "5", "ingredients_equipments": ["Manual Comedone Extractor", "Loop Extractor", "Alcohol Swabs", "Gauze Pads"]}, {"duration": "3 minutes", "how_to_do": "Post-extraction sanitation. Use mushroom electrode on ozone mode, intensity low. Glide over T‑zone with tiny circular motions for 2–3 minutes, never stationary more than 2 seconds per point. Avoid metal contact and pacemaker areas.", "step_number": "6", "ingredients_equipments": ["High-Frequency Machine"]}, {"duration": "2 minutes", "how_to_do": "Oxygen hydration spray across entire face from 10–12 cm distance, sweeping motion. Focus 2 extra passes over cheeks to calm. Pat dry.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine (Oxygen Injection / Hydra spray)", "Hydrafacial Serum A03"]}, {"duration": "14 minutes", "how_to_do": "Position LED panel 15–20 cm from face. Blue mode for 8 minutes to reduce C. acnes in T‑zone. Switch to Red mode for 6 minutes to calm erythema and support barrier. Use eye shields; stop if heat discomfort occurs.", "step_number": "8", "ingredients_equipments": ["LED Light Therapy Machine (Blue, Red)"]}, {"duration": "7 minutes", "how_to_do": "Create infusion cocktail: HA + TRX A for face; HA + PDRN for peri-orbital. Apply pH gel for slip. With face probe, infuse along vectors: from nasolabial to ear, cheek to temple, forehead center to temples—slow linear passes, 2 passes per line at medium energy. With ocular probe, treat infraorbital zone using micro-circular motions, 2 passes each eye; avoid lower lash line by 5–7 mm.", "step_number": "9", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "Hyaluronic Acid (jet infusion solution)", "TRX A (Tranexamic Acid)", "PDRN", "pH Neutral Gel"]}, {"duration": "6 minutes", "how_to_do": "Apply Hydrate mask evenly; build slightly thicker layer on cheeks and under-eyes. Leave 5–6 minutes until set; lift off from edges upward. Check for any redness; if present, cool compress with distilled water.", "step_number": "10", "ingredients_equipments": ["Hydrate Peel-Off Mask", "Mask Applicator Brush"]}, {"duration": "5 minutes", "how_to_do": "Finishers (mandatory). Press a pea-size HA serum over damp skin; follow with a thin layer of Hydrating Gel Base to lock moisture. Apply broad-spectrum SPF50 generously; include nose and peri-oral. For lips, add a thin layer of sunscreen or SPF lip balm.", "step_number": "11", "ingredients_equipments": ["Hyaluronic Acid serum", "Hydrating Gel Base (moisturizer)", "Broad-spectrum Sunscreen SPF50"]}]',
                'status' => 'pending',
                'created_at' => '2025-12-09 11:16:46',
                'updated_at' => '2025-12-09 11:16:46',
