            'preparations_checklist_for_therapist' => '["Verify no new photosensitizing drugs; confirm no allergies to Vitamin C or peel components.", "Obtain informed consent; mark sensitive zones (peri-orbital, corners of nose, lip vermilion).", "Room: bright, sanitized; LED machine and Hydrafacial Machine powered on; set clean tips & tubing.", "Prepare Hydrafacial serums: AS1 (cleanse/exfoliate), SA2 (oil control for T‑zone), A03 (hydration).", "Lay out Jet Infusion solutions: Tranexamic Acid (TRX A), Vitamin C, Hyaluronic Acid, optional PDRN.", "Arrange Chemical Peel: Gel Based Mandelic Peel with fan brush; keep Distilled Water and Gauze Pads for removal.", "Set High-Frequency machine with mushroom electrode for post-extraction sanitation.", "Load Ultrasound Infusion Probe (Face + Ocular) with pH Neutral Gel; keep Hydrating Gel Base ready as barrier for lips.", "Prepare Peel-off Mask: Brighten or Hydrate based on real-time sensitivity.", "Finishers at trolley end: hydrating serum, moisturizer, broad-spectrum sunscreen SPF50.", "Safety kit: Alcohol swabs, cotton pads, waste bin; timer; cool compress for any irritation.", "Photography before/after for records."]',
                'concerns_addressed' => '[{"concern": "Superficial Pigmentation Scoring", "target_value": "3", "current_value": "4"}, {"concern": "Skin Hydration Score", "target_value": "4", "current_value": "3"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "4", "current_value": "3"}, {"concern": "Textural Radiance Index", "target_value": "4", "current_value": "3"}, {"concern": "Texture & Open Pores Score", "target_value": "2", "current_value": "3"}, {"concern": "Peri-Orbital Health Score", "target_value": "2", "current_value": "3"}, {"concern": "Lip Pigmentation Score", "target_value": "2", "current_value": "3"}, {"concern": "Skin Sebum Index", "target_value": "2", "current_value": "3"}, {"concern": "Visual Acne Grading", "target_value": "2", "current_value": "2"}, {"concern": "Vascularity / Redness Scoring", "target_value": "2", "current_value": "2"}]',
            'steps' => '[{"duration": "3 minutes", "how_to_do": "Pre-cleanse with AS1 using the Suction Probe on LOW vacuum; 1 slow pass per zone from medial to lateral; avoid direct suction on peri‑orbital and lip vermilion. Rinse and pat dry.", "step_number": "1", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum AS1", "Cleansing Towels"]}, {"duration": "6 minutes", "how_to_do": "Lymphatic drainage massage: light pressure 25–30 mmHg. Sequence both sides: forehead strokes to temples (8 strokes), cheeks to preauricular nodes (8 strokes/side), jawline to submandibular nodes (8 strokes/side), submental glides to laterals (6 strokes), then down to supraclavicular nodes (6 strokes). Monitor for dizziness; stop if discomfort.", "step_number": "2", "ingredients_equipments": ["Manual technique", "Hydrating Gel Base"]}, {"duration": "8 minutes", "how_to_do": "Decongest + exfoliate. T‑zone: use SA2, VACUUM = LOW→MED, 2 passes vertical then horizontal on nose and chin; cheeks/forehead: AS1 with single pass. Keep the tip moving; do not hover >2 seconds at one spot. Avoid erythema > grade 2.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Suction Probe / Bubble Pen", "Hydrafacial Serum SA2", "Hydrafacial Serum AS1"]}, {"duration": "3 minutes", "how_to_do": "Spot-brightening peel. Apply a thin layer with fan brush to malar cheeks, nose, and peri‑oral zone; avoid eye sockets and corners of lips (protect with Hydrating Gel Base). Contact time 90–150 seconds depending on erythema. Fan for comfort. Neutralize by thorough wipe with distilled water–soaked gauze until skin pH normalizes and stinging stops. Stop immediately if frosting, burning, or excessive redness.", "step_number": "4", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan Brush", "Gauze Pads", "Distilled Water", "Hydrating Gel Base"]}, {"duration": "7 minutes", "how_to_do": "Targeted extractions on nose, chin, medial cheeks. Angle loop at 45°; press and roll gently along follicular line. Limit to 5–7 minutes to avoid edema. Wipe with alcohol swab between lesions.", "step_number": "5", "ingredients_equipments": ["Manual Comedone Extractor", "Loop Extractor", "Alcohol Swabs"]}, {"duration": "2 minutes", "how_to_do": "Post-extraction sanitation. Intensity LOW; perform sparking touches on extracted pores, then glide passes across T‑zone for total 2 minutes. Avoid peri‑orbital region and active dermatitis.", "step_number": "6", "ingredients_equipments": ["High-Frequency Machine (mushroom electrode)"]}, {"duration": "6 minutes", "how_to_do": "Jet infusion for pigment. Mix TRX A + Vitamin C (1:1). Using Oxygen Injection, spray in cross-hatching passes 10 cm from skin over malar cheeks, nose bridge/tip, upper lip. 2 passes per zone. Wipe excess; avoid eyes.", "step_number": "7", "ingredients_equipments": ["Hydrafacial Machine", "Oxygen Injection (Hydra spray)", "TRX A (Tranexamic Acid)", "Vitamin C"]}, {"duration": "7 minutes", "how_to_do": "Deep hydration + peri‑orbital care. Blend Hyaluronic Acid + PDRN (1:1). Face probe at 40–50% energy with continuous mode; slow circular strokes for 5 minutes across full face. Switch to ocular probe 20–30% energy for 2 minutes along infra‑orbital arc, moving from inner canthus to lateral canthus; never rest probe; keep gel buffer to avoid heat. Stop if flashing light sensations or discomfort.", "step_number": "8", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "pH Neutral Gel", "Hyaluronic Acid", "PDRN"]}, {"duration": "13 minutes", "how_to_do": "LED sequence: Blue mode 5 minutes concentrating on T‑zone (anti‑bacterial, sebum modulation) with panel 10–12 cm from face; then Red mode 8 minutes full face for inflammation control and healing. Protect eyes with goggles throughout.", "step_number": "9", "ingredients_equipments": ["LED Light Therapy Machine (Blue, Red)"]}, {"duration": "8 minutes", "how_to_do": "Choose based on sensitivity: If cheeks appear reactive, use Hydrate; otherwise Brighten. Apply evenly avoiding nostrils and eyes; leave 6–8 minutes until set, then peel from edges upward following skin tension lines.", "step_number": "10", "ingredients_equipments": ["Peel-off Mask: Brighten", "Peel-off Mask: Hydrate"]}, {"duration": "3 minutes", "how_to_do": "Mandatory finish. Layer hydrating/brightening serum thinly; seal with moisturizer. Apply broad-spectrum SPF50 generously to entire face and lips’ vermilion border. Provide post-care: avoid heat/exercise for 24h; strict SPF reapplication.", "step_number": "11", "ingredients_equipments": ["Serum (Hyaluronic or TRX A blend)", "Moisturizer", "Sunscreen SPF50"]}]',
