            'preparations_checklist_for_therapist' => '["Confirm allergy: Glycolic Acid → avoid all glycolic peels (Glyco Peel 35).", "Discuss goals: hydration, glow, pigmentation, under‑eye. Obtain consent and photos.", "Patch test Gel Based Mandelic Peel at mandibular angle for 2 minutes before main application.", "Prepare Hydrafacial Machine: Suction Probe/Bubble Pen (low suction), Cutin Removal Spatula, Oxygen Injection (Hydra spray).", "Prepare Ultrasound Infusion Probes: Face + Ocular with pH Neutral Gel.", "Prepare LED Light Therapy Machine: Green + Red modes.", "Prepare Radio Frequency Machine (Lifting Probe) → energy 3–4 (mild), gel ready.", "Products to keep ready: Hyaluronic Acid, TRX A (Tranexamic Acid), PDRN solutions; Gel Based Mandelic Peel; Hydrate peel‑off mask; hydrating gel base; broad‑spectrum SPF.", "Ensure room temperature cool, fan ready for peel comfort, cotton/gauze pads & distilled water for neutralization.", "Check metal jewelry removed; protect eyes with eye shields during LED/RF; sanitize tools and hands."]',
                'concerns_addressed' => '[{"concern": "Barrier Health + Sensitivity", "target_value": "2", "current_value": "3"}, {"concern": "Skin Hydration Score", "target_value": "3", "current_value": "2"}, {"concern": "Skin Luminosity / Glow Index", "target_value": "3", "current_value": "2"}, {"concern": "Superficial Pigmentation Scoring", "target_value": "3", "current_value": "4"}, {"concern": "Peri-Orbital Health Score", "target_value": "3", "current_value": "4"}, {"concern": "Texture & Open Pores Score", "target_value": "2", "current_value": "3"}, {"concern": "Textural Radiance Index", "target_value": "2", "current_value": "3"}, {"concern": "Skin Sebum Index", "target_value": "3", "current_value": "2"}, {"concern": "Vascularity / Redness", "target_value": "1", "current_value": "2"}]',
            'steps' => '[{"duration": "5 minutes", "how_to_do": "Double cleanse with gentle motions; pat dry. Re‑confirm glycolic allergy and review patch test area for Mandelic peel tolerance (no wheal/erythema).", "step_number": "1", "ingredients_equipments": ["Cleansing Towels", "Distilled Water", "Hydrafacial Serum A03 (Hydration)"]}, {"duration": "6 minutes", "how_to_do": "Perform lymphatic drainage: start at supraclavicular nodes (10 gentle pumps each side). From mid‑face glide to pre‑auricular/parotid nodes then down to clavicle; submental → along mandible to angles then down. Pressure: light (lymph level), rhythm 1 second per stroke. Avoid direct pressure on under‑eye.", "step_number": "2", "ingredients_equipments": ["Hydrating Gel Base", "Manual Lymphatic Massage (hands)"]}, {"duration": "8 minutes", "how_to_do": "Low suction setting; single slow pass per strip. Sequence: forehead → temples → cheeks → nose (2 cross‑hatch passes) → chin. Keep tip parallel to skin at 15–20° angle, continuous motion to avoid petechiae.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Cutin Removal Spatula (Exfoliator)", "Suction Probe / Bubble Pen", "Hydrafacial Serum A03"]}, {"duration": "3 minutes", "how_to_do": "Only if visible plugs on nose. Disinfect tip; press gently with loop at 45° along pore axis; stop if bleeding/bruise; limit to <10 extractions.", "step_number": "4", "ingredients_equipments": ["Manual Comedone Extractor"]}, {"duration": "5 minutes (contact 3–4 minutes)", "how_to_do": "Apply thin, even layer avoiding eyelids, corners of nose/lips. Start timer immediately. Observe frosting/erythema; if stinging >6/10, neutralize early with copious water. Do not use on under‑eye or active cuts.", "step_number": "5", "ingredients_equipments": ["Gel Based Mandelic Peel", "Fan Brush", "Gauze Pads", "Distilled Water"]}, {"duration": "3 minutes", "how_to_do": "After thorough water rinse, cool the skin with oxygen spray in sweeping passes 10–15 cm from face to reduce heat and sensitivity.", "step_number": "6", "ingredients_equipments": ["Hydrafacial Machine", "Oxygen Injection (Hydra spray)", "Calming gauze"]}, {"duration": "8 minutes", "how_to_do": "Mix HA 1 ml + TRX A 1 ml + PDRN 1 ml. Apply gel; use continuous ultrasound mode, slow linear strokes upward on cheeks and circular on forehead. Keep probe flat with gentle pressure; 2–3 passes per zone. Avoid thyroid and open lesions.", "step_number": "7", "ingredients_equipments": ["Face Ultrasound Infusion Probe", "pH Neutral Gel", "Hyaluronic Acid", "TRX A (Tranexamic Acid)", "PDRN"]}, {"duration": "5 minutes", "how_to_do": "For infra‑orbital: apply thin gel film; use ocular probe at low intensity in feather‑light circular motions from inner canthus outward, staying 1 cm below lash line. 2 passes per side (approx. 2–2.5 min each). Stop if tearing or warmth >mild.", "step_number": "8", "ingredients_equipments": ["Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "PDRN", "pH Neutral Gel"]}, {"duration": "6 minutes", "how_to_do": "Lower‑face contouring only. Energy 3–4 (mild). Keep probe moving with overlapping circles along jawline and marionette zone, vectoring strokes upward toward tragus and pre‑auricular nodes. Target surface temperature comfort (warm, not hot). 2 passes each side; stop if persistent erythema.", "step_number": "9", "ingredients_equipments": ["Radio Frequency Machine", "Lifting Probe (RF)", "pH Neutral Gel"]}, {"duration": "12 minutes", "how_to_do": "Eyes protected. Green mode 6 minutes full face focusing cheeks/upper lip for pigment modulation (15–20 cm distance). Switch to Red mode 6 minutes for barrier repair and micro‑inflammation calming; hold equal distance.", "step_number": "10", "ingredients_equipments": ["LED Light Therapy Machine (Green, Red)"]}, {"duration": "8 minutes", "how_to_do": "Apply thick even layer avoiding nostrils/eyes; allow to set 6–8 minutes. Peel off from edges upward; wipe residues with distilled water.", "step_number": "11", "ingredients_equipments": ["Hydrate Peel‑off Mask"]}, {"duration": "3 minutes", "how_to_do": "Finish as mandated: press-in HA serum across face and under-eye; seal with moisturizer; apply broad‑spectrum SPF 50 generously to face and lips (lip-safe SPF balm).", "step_number": "12", "ingredients_equipments": ["Hyaluronic Acid (serum)", "Moisturizer (ceramide/oil-in-water base)", "Sunscreen SPF50"]}]',
