            'steps' => '[{"duration": "4", "how_to_do": "Double cleanse with damp towels; pat dry. Degrease T‑zone lightly with alcohol swabs to remove surface oil without over-rubbing.", "step_number": "1", "ingredients_equipments": ["Cleansing Towels", "Distilled Water", "Alcohol Swabs"]}, {"duration": "6", "how_to_do": "Manual lymphatic drainage: With gel slip, perform gentle pumps from mid‑forehead to temporal nodes; from nose sidewalls sweep to pre‑auricular nodes; from chin/jaw sweep to submandibular nodes. Pressure light, 5–7 strokes per pathway; avoid dragging over active papules.", "step_number": "2", "ingredients_equipments": ["Hydrating Gel Base"]}, {"duration": "10", "how_to_do": "Exfoliate using Cutin Removal Spatula in upward strokes across forehead and cheeks for 2 minutes. Switch to Suction Probe with SA2: Forehead 2 passes (horizontal then vertical), Nose 3 slow passes focusing on alar grooves, Cheeks medial zone 2 passes each, Chin 2 passes. Keep suction medium; keep the tip moving to avoid petechiae.", "step_number": "3", "ingredients_equipments": ["Hydrafacial Machine", "Hydrafacial Serum SA2", "Cutin Removal Spatula (Exfoliator)", "Suction Probe / Bubble Pen"]}, {"duration": "6", "how_to_do": "Target only open comedones/blackheads on nose and medial cheeks. Stretch skin with gauze; gentle vertical pressure with loop; stop if bleeding or if lesion resists after 2 attempts.", "step_number": "4", "ingredients_equipments": ["Manual Comedone Extractor", "Loop Extractor", "Gauze Pads"]}, {"duration": "3", "how_to_do": "Post-extraction sanitation. Use glass electrode in tapping motions over extracted areas and active papules for 1–2 seconds each; total 3 minutes. Avoid metal contact; stop if patient feels sharp zaps.", "step_number": "5", "ingredients_equipments": ["High-Frequency Machine"]}, {"duration": "8", "how_to_do": "Apply a thin, even layer of Carbon Lotion over entire face avoiding eyes/lips; allow 8 minutes for penetration and drying. Confirm matte carbon appearance before laser.", "step_number": "6", "ingredients_equipments": ["Carbon Lotion"]}, {"duration": "12", "how_to_do": "Carbon Q-Switch Toning: Use 1064nm, frequency 6–8 Hz, energy 600–900 mJ (start low and increase by 50 mJ steps as tolerated). Hold handpiece 90° to skin, move in 10–15% overlap swipes. Pass 1 full face focusing on nose/medial cheeks; Pass 2 spot over pigment clusters and oily T‑zone. Endpoints: crisp acoustic pop, carbon ablation, mild warmth; avoid skin frosting/whitening. Stop immediately if hot pain or persistent erythema occurs.", "step_number": "7", "ingredients_equipments": ["Q-Switch Laser", "Protective Eye Shields"]}, {"duration": "2", "how_to_do": "Wipe off residual carbon thoroughly; cool compress if needed.", "step_number": "8", "ingredients_equipments": ["Cleansing Towels", "Distilled Water"]}, {"duration": "8", "how_to_do": "Ultrasound infusion. Mix TRX A with Hyaluronic in 1:1 for face. Use Face Ultrasound Probe with gel slip at slow circular motions: cheeks 2 min each, forehead 1.5 min, nose 1 min, chin 1.5 min. Switch to Ocular Probe: under-eye arcs from inner to outer canthus 1 min per side with TRX A only; keep 5 mm away from lash line.", "step_number": "9", "ingredients_equipments": ["Hydrafacial Machine", "Face Ultrasound Infusion Probe", "Ocular Ultrasound Infusion Probe", "TRX A (Tranexamic Acid)", "Hyaluronic Acid", "pH Neutral Gel (for RF, Ultrasound)"]}, {"duration": "14", "how_to_do": "Position LEDs 15–20 cm from face with eye goggles on. Run Blue mode for 8 minutes to reduce C. acnes activity; immediately follow with Red mode for 6 minutes to calm inflammation and speed repair.", "step_number": "10", "ingredients_equipments": ["LED Light Therapy Machine"]}, {"duration": "7", "how_to_do": "Apply Brighten peel-off mask evenly, avoiding eyes and lips; leave for 7 minutes until semi-dry; peel gently from edges. This boosts radiance while keeping irritation low post-laser.", "step_number": "11", "ingredients_equipments": ["Brighten"]}, {"duration": "2", "how_to_do": "Serum application (mandatory finisher step 1): Apply Hyaluronic Acid serum in light press motions across all zones; extra layer on cheeks for hydration.", "step_number": "12", "ingredients_equipments": ["Hyaluronic Acid"]}, {"duration": "2", "how_to_do": "Moisturizer application (mandatory finisher step 2): Massage Hydrating Gel Base gently to seal hydration; avoid heavy occlusion on T‑zone.", "step_number": "13", "ingredients_equipments": ["Hydrating Gel Base"]}, {"duration": "2", "how_to_do": "Sunscreen application (mandatory finisher step 3): Apply a broad-spectrum sunscreen evenly; instruct patient to reapply every 3–4 hours today.", "step_number": "14", "ingredients_equipments": ["Sunscreen"]}]',
